```js
// —— 网格布局：把当前层级房间排成整齐的方框网格，连线全部横平竖直 ——
let _layoutCache=null; // {key, pos, w, h}
function layoutKey(){ return (game.mapLevel||'zhou')+'|'+(game.cheng||'')+'|'+(game.bld||''); }
function layoutNodes(){
  // returns {nodes:[], edges:[[a,b]], root}
  const lv=game.mapLevel||'zhou';
  if(lv==='zhou'){
    const nodes=Object.keys(CHENG_CFG);
    const edges=CHENG_LINKS.map(p=>[p[0],p[1]]);
    const root=CHENG_CFG[player.room]?player.room:(game.cheng||'cheng_lizhu');
    return {nodes, edges, root: CHENG_CFG[root]?root:nodes[0]};
  }
  const cid=game.cheng;
  const nodes=[];
  const edgeSet={};
  const addE=(a,b)=>{ const k=[a,b].sort().join('|'); if(!edgeSet[k] && a!==b){ edgeSet[k]=1; } };
  for(const rn in ROOMS){
    const r=ROOMS[rn];
    if(lv==='cheng'){ if(r.area===cid && typeof r.bld!=='string') nodes.push(rn); }
    else { if(r.bld===game.bld) nodes.push(rn); }
  }
  const nodeSet={}; nodes.forEach(n=>nodeSet[n]=1);
  nodes.forEach(rn=>{
    const r=ROOMS[rn]; if(!r||!r.exits) return;
    for(const d in r.exits){ const t=r.exits[d]; if(nodeSet[t]) addE(rn,t); }
  });
  const edges=Object.keys(edgeSet).map(k=>k.split('|'));
  let root=player.room;
  if(nodeSet[root]!==1){ root=nodes[0]||''; }
  return {nodes, edges, root};
}
function gridLayout(){
  const key=layoutKey();
  if(_layoutCache && _layoutCache.key===key) return _layoutCache;
  const {nodes, edges, root}=layoutNodes();
  // adjacency
  const adj={}; nodes.forEach(n=>adj[n]=[]);
  edges.forEach(([a,b])=>{ adj[a].push(b); adj[b].push(a); });
  // BFS depth
  const depth={}; const order=[];
  const seen={}; 
  if(root!==undefined && root!=='' && nodes.indexOf(root)>-1){ seen[root]=1; depth[root]=0; }
  let q=seen[root]?[root]:[];
  while(q.length){
    const cur=q.shift(); order.push(cur);
    (adj[cur]||[]).forEach(nb=>{ if(!seen[nb]){ seen[nb]=1; depth[nb]=depth[cur]+1; q.push(nb); } });
  }
  // handle disconnected nodes
  nodes.forEach(n=>{ if(!seen[n]){ seen[n]=1; depth[n]=999; order.push(n); } });
  // group by depth
  const cols={}; order.forEach(n=>{ const d=depth[n]; (cols[d]=cols[d]||[]).push(n); });
  const depths=Object.keys(cols).sort((a,b)=>a-b);
  // barycenter ordering within each column (a few passes)
  const rowOf={}; // row index within column
  cols[depths[0]].forEach((n,i)=>rowOf[n]=i);
  for(let pass=0; pass<5; pass++){
    for(let di=1; di<depths.length; di++){
      const d=depths[di]; const col=cols[d];
      col.forEach(n=>{
        const nbs=adj[n].filter(x=>depth[x]===d-1);
        if(nbs.length){ rowOf[n]=nbs.reduce((s,x)=>s+rowOf[x],0)/nbs.length; }
        else rowOf[n]=0;
      });
      col.sort((a,b)=>rowOf[a]-rowOf[b]);
      col.forEach((n,i)=>rowOf[n]=i);
      // shift to center
    }
    // backward pass
    for(let di=depths.length-2; di>=1; di--){
      const d=depths[di]; const col=cols[d];
      col.forEach(n=>{
        const nbs=adj[n].filter(x=>depth[x]===d+1);
        if(nbs.length){ rowOf[n]=nbs.reduce((s,x)=>s+rowOf[x],0)/nbs.length; }
      });
      col.sort((a,b)=>rowOf[a]-rowOf[b]);
      col.forEach((n,i)=>rowOf[n]=i);
    }
  }
  // compact rows: normalize rowOf to consecutive ints
  ...
  // compute coordinates
  const CELL_W = (game.mapLevel==='zhou')?270:240;
  const CELL_H = (game.mapLevel==='zhou')?180:160;
  const PAD = 120;
  const pos={};
  let maxR=0;
  depths.forEach((d,di)=>{
    const col=cols[d];
    col.forEach((n,i)=>{ rowOf[n]=i; });
    const rows=col.length;
    const colH=(rows-1)*CELL_H;
    col.forEach((n,i)=>{
      pos[n]={ x:PAD+di*CELL_W, y:PAD+colH/2 + i*CELL_H };
    });
    maxR=Math.max(maxR, colH);
  });
  const w=PAD*2+(depths.length-1)*CELL_W+CELL_W;
  const h=PAD*2+maxR+CELL_H;
  _layoutCache={key, pos, w, h};
  return _layoutCache;
}
```

