```js
function recuperate(){
  // 调养：居家/客栈/打坐
  if(game._walking){ logInfo('（你正在赶路……）'); return; }
  if(player.manor && player.manor.tier){ restAtHome(); return; }
  if(isInnRoom()){ restAtInn(); return; }
  // 打坐调息
  if(player.hp>=player.maxHp && player.mp>=player.maxMp){ log('（你神完气足，无需调养）','sys'); return; }
  if(game.restCd>0){ log('（刚调养过——再等 '+(game.restCd)+' 回合）','sys'); return; }
  game.restCd=4;
  player.hp=Math.min(player.maxHp, player.hp+Math.floor(player.maxHp*0.3));
  player.mp=Math.min(player.maxMp, player.mp+Math.floor(player.maxMp*0.3));
  advanceTime(2);
  logSuccess('（你寻了处清净地打坐调息——气血渐复。生命/内力 +30%）');
  updateSidebar(); renderMap();
