let _layerLayout=null;
function layerKey(){ return (game.mapLevel||'zhou')+'|'+(game.cheng||'')+'|'+(game.bld||''); }
function layerRoomsForLayout(){
  const lv=game.mapLevel||'zhou';
  if(lv==='zhou') return Object.keys(CHENG_CFG);
  const cid=game.cheng;
  const out=[];
  for(const rn in ROOMS){
    const r=ROOMS[rn];
    if(lv==='cheng'){ if(r.area===cid && typeof r.bld!=='string') out.push(rn); }
    else { if(r.bld===game.bld) out.push(rn); }
  }
  return out;
}
function layerEdgesForLayout(nodes){
  const lv=game.mapLevel||'zhou';
  const edges=[]; const seen={};
  const push=(a,b)=>{ const k=[a,b].sort().join('|'); if(!seen[k]){ seen[k]=1; edges.push([a,b]); } };
  if(lv==='zhou'){
    CHENG_LINKS.forEach(p=>push(p[0],p[1]));
    return edges;
  }
  nodes.forEach(rn=>{
    const r=ROOMS[rn]; if(!r||!r.exits) return;
    for(const d in r.exits){ const t=r.exits[d]; if(nodes.indexOf(t)>-1) push(rn,t); }
  });
  return edges;
}
