function drawLink(svg, x1,y1,x2,y2, cls, boxW, boxH){
  // clamp start/end to box edges
  const dx=x2-x1, dy=y2-y1;
  const hw=boxW/2, hh=boxH/2;
  let sx=x1, sy=y1, ex=x2, ey=y2;
  // start from edge facing target
  if(Math.abs(dx)>=Math.abs(dy)){
    sx = x1 + (dx>0?hw:-hw);
    ex = x2 - (dx>0?hw:-hw);
  } else {
    sy = y1 + (dy>0?hh:-hh);
    ey = y2 - (dy>0?hh:-hh);
  }
  const path=document.createElementNS(SVG_NS,'path');
  let d;
  if(Math.abs(sy-ey)<1){ d='M'+sx+' '+sy+' L'+ex+' '+ey; }
  else {
    const mx=(sx+ex)/2;
    d='M'+sx+' '+sy+' L'+mx+' '+sy+' L'+mx+' '+ey+' L'+ex+' '+ey;
  }
  path.setAttribute('d',d);
  path.setAttribute('class',cls);
