Layout algorithm (layered BFS with barycenter ordering):

```js
function computeGridLayout(nodes, edges, root){
  // nodes: array of names
  // edges: array of [a,b]
  const adj={}; nodes.forEach(n=>adj[n]=[]);
  edges.forEach(([a,b])=>{ adj[a].push(b); adj[b].push(a); });
  // BFS depth
  const depth={}; const seen={}; const queue=[root]; seen[root]=1; depth[root]=0;
  let qi=0;
  while(qi<queue.length){ const cur=queue[qi++]; (adj[cur]||[]).forEach(nb=>{ if(!seen[nb]){ seen[nb]=1; depth[nb]=depth[cur]+1; queue.push(nb); } }); }
  // unconnected nodes → put in extra columns
  nodes.forEach(n=>{ if(!seen[n]){ seen[n]=1; depth[n]=999; } });
  // group by depth
  const cols={}; nodes.forEach(n=>{ (cols[depth[n]]=cols[depth[n]]||[]).push(n); });
  // sort columns by depth key
  const colKeys=Object.keys(cols).map(Number).sort((a,b)=>a-b);
  // barycenter ordering within each column (a few passes)
  const order={}; // order within column
  colKeys.forEach(d=>{ cols[d].forEach((n,i)=>order[n]=i); });
  for(let pass=0; pass<8; pass++){
    // forward: for each column except first, sort by avg position of neighbors in previous column
    for(let c=1;c<colKeys.length;c++){
      const d=colKeys[c];
      cols[d].forEach(n=>{
        const nbs=(adj[n]||[]).filter(x=>depth[x]===colKeys[c-1]);
        if(nbs.length) order[n]=nbs.reduce((s,x)=>s+order[x],0)/nbs.length;
      });
      cols[d].sort((a,b)=>order[a]-order[b]);
      cols[d].forEach((n,i)=>order[n]=i);
    }
    // backward
    for(let c=colKeys.length-2;c>=0;c--){
      const d=colKeys[c];
      cols[d].forEach(n=>{
        const nbs=(adj[n]||[]).filter(x=>depth[x]===colKeys[c+1]);
        if(nbs.length) order[n]=nbs.reduce((s,x)=>s+order[x],0)/nbs.length;
      });
      cols[d].sort((a,b)=>order[a]-order[b]);
      cols[d].forEach((n,i)=>order[n]=i);
    }
  }
  // normalize rows to consecutive integers per column
  colKeys.forEach(d=>{ cols[d].forEach((n,i)=>order[n]=i); });
  // coordinates
  const CELL_W=..., CELL_H=..., PAD=...;
  const pos={};
  let maxRows=0;
  colKeys.forEach((d,ci)=>{
    const col=cols[d];
    maxRows=Math.max(maxRows,col.length);
    const colH=(col.length-1)*CELL_H;
    col.forEach((n,ri)=>{
      pos[n]={ x: PAD+ci*CELL_W, y: PAD+colH/2 + ri*CELL_H }; // center column vertically
    });
  });
  const w = PAD*2 + (colKeys.length-1)*CELL_W;
  const h = PAD*2 + (maxRows-1)*CELL_H;
  return {pos, w, h};
}
```

