// —— 网格布局：把当前层级房间排成整齐的方框阵，连线横平竖直 ——
let _layerLayout=null;
function layerKey(){ return (game.mapLevel||'zhou')+'|'+(game.cheng||'')+'|'+(game.bld||''); }
function layerRoomsForLayout(){
  const lv=game.mapLevel||'zhou';
  if(lv==='zhou') return Object.keys(CHENG_CFG);
  const cid=game.cheng;
  const out=[];
  for(const rn in ROOMS){
