    else { if(r.bld===game.bld) out.push(rn); }
  }
  return out;
}
function layerEdgesForLayout(nodes){
  const lv=game.mapLevel||'zhou';
  const edges=[]; const seen={};
  const push=(a,b)=>{ const k=[a,b].sort().join('|'); if(!seen[k]){ seen[k]=1; edges.push([a,b]); } };
  if(lv==='zhou'){
    CHENG_LINKS.forEach(p=>push(p[0],p[1]));
    return edges;
  }
  nodes.forEach(rn=>{
    const r=ROOMS[rn]; if(!r||!r.exits) return;
    for(const d in r.exits){ const t=r.exits[d]; if(nodes.indexOf(t)>-1) push(rn,t); }
  });
  return edges;
}
function gridLayout(){
  const key=layerKey();
  if(_layerLayout && _layerLayout.key===key) return _layerLayout;
  const lv=game.mapLevel||'zhou';
  const nodes=layerRoomsForLayout();
  const edges=layerEdgesForLayout(nodes);
  // root
  let root=null;
  if(lv==='zhou'){ root=CHENG_CFG[player.room]?player.room:'cheng_lizhu'; }
  else if(nodes.indexOf(player.room)>-1) root=player.room;
  else root=nodes[0];
  const cellW=lv==='zhou'?320:270;
  const cellH=lv==='zhou'?230:200;
  const pad=120;
  const res=computeGridLayout(nodes, edges, root, cellW, cellH, pad);
  res.key=key;
  _layerLayout=res;
  return res;
}
