Let me write the layout function carefully:

```js
let _layoutCache=null;
function layerLayout(force){
  const lv=game.mapLevel||'zhou';
  const cid=game.cheng||'';
  const bld=game.bld||'';
  const key=lv+'|'+cid+'|'+bld;
  if(_layoutCache && _layoutCache.key===key && !force) return _layoutCache;
  // gather nodes & edges (undirected, dedup)
  const nodes=[], set={}, edges=[], seen={};
  if(lv==='zhou'){
    Object.keys(CHENG_CFG).forEach(n=>{ nodes.push(n); set[n]=1; });
    CHENG_LINKS.forEach(p=>{
      const k=[p[0],p[1]].sort().join('|');
      if(seen[k]||!set[p[0]]||!set[p[1]]) return; seen[k]=1;
      edges.push(p);
    });
  } else {
    const isNei=lv==='nei';
    for(const rn in ROOMS){
      const r=ROOMS[rn];
      if(isNei){ if(r.bld===bld){ nodes.push(rn); set[rn]=1; } }
      else { if(r.area===cid && typeof r.bld!=='string'){ nodes.push(rn); set[rn]=1; } }
    }
    nodes.forEach(rn=>{
      const r=ROOMS[rn]; if(!r||!r.exits) return;
      for(const d in r.exits){
        const t=r.exits[d];
        if(!set[t]) continue;
        const k=[rn,t].sort().join('|');
        if(seen[k]) continue; seen[k]=1;
        edges.push([rn,t]);
      }
    });
  }
  // BFS depth
  const root = (set[player.room])?player.room:(lv==='zhou'?(set['cheng_lizhu']?'cheng_lizhu':nodes[0]):(nodes[0]||''));
  const adj={}; nodes.forEach(n=>adj[n]=[]);
  edges.forEach(e=>{ adj[e[0]].push(e[1]); adj[e[1]].push(e[0]); });
  const depth={}, col={}; 
  nodes.forEach(n=>depth[n]=-1);
  if(root!==undefined && root!=='' && set[root]){ depth[root]=0; }
  const q=[root]; let qi=0;
  // BFS
  if(root!==undefined && root!=='' && set[root]){
    while(qi<q.length){
      const cur=q[qi++];
      (adj[cur]||[]).forEach(nb=>{ if(depth[nb]===-1){ depth[nb]=depth[cur]+1; q.push(nb); } });
    }
  }
  // disconnected nodes → put at end (depth = max+1... assign incremental)
  let maxD=0; nodes.forEach(n=>{ if(depth[n]>maxD) maxD=depth[n]; });
  let extra=maxD+1;
  nodes.forEach(n=>{ if(depth[n]===-1){ depth[n]=extra; extra++; } });
  // group by depth
  const cols={};
  nodes.forEach(n=>{ (cols[depth[n]]=cols[depth[n]]||[]).push(n); });
  const depths=Object.keys(cols).map(Number).sort((a,b)=>a-b);
  // order within each column: barycenter (average row of neighbors in prev/next column), few passes
  const order={}; // n -> index within column
  depths.forEach(d=>{ cols[d].sort(); cols[d].forEach((n,i)=>order[n]=i); });
  for(let pass=0; pass<10; pass++){
    // forward
    for(let ci=1; ci<depths.length; ci++){
      const d=depths[ci];
      cols[d].forEach(n=>{
        const nbs=(adj[n]||[]).filter(x=>depth[x]===depths[ci-1]);
        if(nbs.length){ order[n]=nbs.reduce((s,x)=>s+order[x],0)/nbs.length; }
      });
      cols[d].sort((a,b)=>order[a]-order[b]);
      cols[d].forEach((n,i)=>order[n]=i);
    }
    // backward
    for(let ci=depths.length-2; ci>=0; ci--){
      const d=depths[ci];
      cols[d].forEach(n=>{
        const nbs=(adj[n]||[]).filter(x=>depth[x]===depths[ci+1]);
        if(nbs.length){ order[n]=nbs.reduce((s,x)=>s+order[x],0)/nbs.length; }
      });
      cols[d].sort((a,b)=>order[a]-order[b]);
      cols[d].forEach((n,i)=>order[n]=i);
    }
  }
  // grid metrics
  const isZhou=lv==='zhou';
  const cellW=isZhou?320:270, cellH=isZhou?210:180, pad=140;
  const bw=isZhou?230:(lv==='nei'?190:200), bh=isZhou?96:(lv==='nei'?80:84);
  const pos={};
  depths.forEach((d,ci)=>{
    const col=cols[d]; const n=col.length;
    const colTop = (n-1)*cellH/2;
    col.forEach((rn,ri)=>{
      pos[rn]={ x: pad+ci*cellW, y: pad+colTop + ri*cellH };
    });
  });
  // size
  let x1=1e9,y1=1e9,x2=-1e9,y2=-1e9;
  nodes.forEach(n=>{ const p=pos[n]; if(p.x-bw/2<x1)x1=p.x-bw/2; if(p.x+bw/2>x2)x2=p.x+bw/2; if(p.y-bh/2<y1)y1=p.y-bh/2; if(p.y+bh/2>y2)y2=p.y+bh/2; });
  const w=x2-x1+pad*2, h=y2-y1+pad*2;
  const res={key:key, pos:pos, w:w, h:h, bw:bw, bh:bh, cx:(x1+x2)/2, cy:(y1+y2)/2};
  _layoutCache=res;
  return res;
}
```

