```js
function orthoLine(svg, x1,y1,x2,y2, bw, bh, cls){
  const path=document.createElementNS(SVG_NS,'path');
  // start from box edge toward target
  const dx=x2-x1, dy=y2-y1;
  let sx=x1, sy=y1, ex=x2, ey=y2;
  if(Math.abs(dx)>=Math.abs(dy)){
    sx=x1+(dx>0?bw/2:-bw/2);
    ex=x2+(dx>0?-bw/2:bw/2);
  } else {
    sy=y1+(dy>0?bh/2:-bh/2);
    ey=y2+(dy>0?-bh/2:bh/2);
  }
  let d;
  if(Math.abs(dy)<0.5){ d='M'+sx+' '+sy+' L'+ex+' '+ey; }
  else {
    const mx=(sx+ex)/2;
    d='M'+sx+' '+sy+' H'+mx+' V'+ey+' H'+ex;
  }
  path.setAttribute('d',d); path.setAttribute('class',cls); path.setAttribute('fill','none');
  svg.appendChild(path);
}
```
