```js
// —— 网格布局：按房间连接关系把当前层级排成整齐的方框网格 ——
function layerLayout(){
  const lv=game.mapLevel||'zhou';
  // collect nodes
  let nodes=[], edges=[];
  if(lv==='zhou'){
    nodes=Object.keys(CHENG_CFG);
    const seen={};
    CHENG_LINKS.forEach(p=>{
      const k=[p[0],p[1]].sort().join('|');
      if(seen[k]) return; seen[k]=1;
      edges.push(p);
    });
  } else {
    const cid=game.cheng;
    const isNei=(lv==='nei');
    for(const rn in ROOMS){
      const r=ROOMS[rn];
      if(isNei){ if(r.bld===game.bld) nodes.push(rn); }
      else { if(r.area===cid && typeof r.bld!=='string') nodes.push(rn); }
    }
    const set={}; nodes.forEach(n=>set[n]=1);
    const seen={};
    nodes.forEach(rn=>{
      const r=ROOMS[rn]; if(!r||!r.exits) return;
      for(const d in r.exits){
        const t=r.exits[d];
        if(!set[t]) continue;
        const k=[rn,t].sort().join('|');
        if(seen[k]) continue; seen[k]=1;
        edges.push([rn,t]);
      }
    });
  }
  // layered layout: BFS depth from root
  ...
}
```

Root: for zhou → the player's current city (if any) else first node; for cheng → player's room if in layer, else entry; for nei → player room if in layer, else first node.

Layered layout algorithm:
1. BFS from root over undirected edges → depth per node.
2. Group nodes by depth → columns.
3. Within each column, order nodes to minimize crossings using barycenter heuristic (average position of neighbors in adjacent columns), a few iterations.
4. Assign coordinates: x = col * cellW + padX, y = row * cellH + padY (with each column vertically centered).
5. Return {pos: {rn: {x,y}}, w, h}.

Cell sizes: cheng/nei rooms: box ~ 200×90; cellW=260, cellH=170. zhou cities: box ~ 230×100; cellW=300, cellH=200.

