// —— 调养（快捷栏按钮）：有宅邸居家休养，否则客栈歇宿；实在不行就地打坐 ——
function restAction(){
  if(battleMode){ log('（战事未了，岂能安然调养）','sys'); return; }
  if(game._walking){ logInfo('（你正在赶路——到了地方再歇脚吧）'); return; }
  if(player.manor && player.manor.tier){ restAtHome(); return; }
  if(/客栈|客房|驿馆/.test(player.room)){ restAtInn(); return; }
  // 就地打坐：恢复少量气血（不耗银两）
  if(game.restCd>0){ log('（刚调养过——再等 '+(game.restCd)+' 回合）','sys'); return; }
  game.restCd=6;
  const hGain=Math.floor(effMaxHp()*0.25), mGain=Math.floor(effMaxMp()*0.25);
  player.hp=Math.min(player.maxHp, player.hp+hGain);
  player.mp=Math.min(player.maxMp, player.mp+mGain);
  if(player.wound>0) player.wound=Math.max(0,player.wound-1);
  advanceTime(2);
  logSuccess('（你寻了处清净地打坐调息——气血渐复。生命 +'+hGain+'，内力 +'+mGain+'，伤势也舒缓了些。）');
  updateSidebar(); renderMap();
}
// —— 疗伤（快捷栏按钮）：敷药疗伤，顺带回血 ——
function healAction(){
