  healWoundAction();
  renderMap();
}
// —— 行囊（快捷栏按钮）：使用消耗品 / 穿戴装备 / 卸下装备 ——
function openBackpack(){
  const h=document.createElement('div');
  const head=document.createElement('div'); head.style.cssText='color:#c9c9cf;font-size:.72em;letter-spacing:2px;margin-bottom:6px;';
  head.textContent='（点击可用的物品直接使用；武器/防具/饰品/衣装点击即穿戴。）';
  h.appendChild(head);
  // 已装备
  const eqHead=document.createElement('div'); eqHead.style.cssText='color:#c9c9cf;font-size:.7em;letter-spacing:3px;margin:6px 0 4px;'; eqHead.textContent='— 已装备 —';
  h.appendChild(eqHead);
  const slotNames=[['weapon','武器'],['armor','防具'],['accessory','饰品'],['garb','衣装']];
  let eqAny=false;
  slotNames.forEach(function(s){
    const name=player.equipment[s[0]];
    if(!name) return;
    eqAny=true;
    const row=document.createElement('div'); row.className='list-row';
    row.innerHTML='<span class="lname">'+s[1]+'：'+itemLabel(name)+'</span>';
    const u=document.createElement('button'); u.className='btn small'; u.textContent='卸下';
    u.addEventListener('click',function(){
      addItem(name); player.equipment[s[0]]=null;
      log('（你卸下了「'+itemLabel(name)+'」。）','sys');
      updateSidebar(); openBackpack();
    });
    row.appendChild(u);
    h.appendChild(row);
  });
  if(!eqAny){ const e=document.createElement('div'); e.style.cssText='color:#b8b8c0;font-size:.74em;padding:4px 8px;'; e.textContent='（未着装备）'; h.appendChild(e); }
  // 行囊
  const invHead=document.createElement('div'); invHead.style.cssText='color:#c9c9cf;font-size:.7em;letter-spacing:3px;margin:10px 0 4px;'; invHead.textContent='— 行 囊 —';
  h.appendChild(invHead);
  if(!player.inventory.length){
    const e=document.createElement('div'); e.style.cssText='color:#b8b8c0;font-size:.74em;padding:4px 8px;';
    e.textContent='（行囊空空——可去集市、店铺购买，或从敌人身上搜罗。）';
    h.appendChild(e);
  } else {
    player.inventory.forEach(function(name){
      const it=itemData(name);
      if(!it) return;
      const row=document.createElement('div'); row.className='list-row';
      let info=it.desc||'';
      if(it.type==='consumable'){
        if(it.effect==='heal') info='恢复生命 '+(it.value||0);
        else if(it.effect==='mana') info='恢复内力 '+(it.value||0);
        else if(it.effect==='exp') info='修为 +'+(it.value||0);
        else if(it.effect==='wound') info='舒缓伤势';
        else if(it.effect==='looks') info='增益容貌';
      } else if(it.type==='weapon'||it.type==='armor'||it.type==='accessory'){
        const score=equipScore(it);
        if(score>0) info='装备评分 '+score;
      }
      row.innerHTML='<span class="lname">'+itemLabel(name)+'</span><span class="lmeta">'+info+'</span>';
      const usable=(it.type==='consumable' || it.type==='weapon' || it.type==='armor' || it.type==='accessory' || it.type==='garb');
      if(usable){
        const b=document.createElement('button');
        b.className='btn small '+(it.type==='consumable'?'green':'blue');
        b.textContent=(it.type==='consumable')?'使用':((it.type==='garb')?'换上':'装备');
        b.addEventListener('click',function(){
          useItem(name);
          updateSidebar();
          openBackpack();
        });
        row.appendChild(b);
      }
      h.appendChild(row);
    });
  }
  openModal('行 囊', ()=>h);
