function drawOrthoLink(svg, x1, y1, x2, y2, hw, hh, cls){
  const dx=x2-x1, dy=y2-y1;
  if(dx===0 && dy===0) return;
  const sx=x1+(dx>=0?hw:-hw), sy=y1;
  const ex=x2+(dx>=0?-hw:hw), ey=y2;
  const path=document.createElementNS(SVG_NS,'path');
  let d;
  if(Math.abs(sy-ey)<3){
    d='M'+sx+' '+sy+' L'+ex+' '+ey;
