const askRestart=newGameReset;

/* ================================================================
   命令处理（文字指令为辅）
   ================================================================ */
function processCommand(raw){
  const t=raw.trim().toLowerCase(); if(!t) return;
  const parts=t.split(/\s+/); const cmd=parts[0]; const args=parts.slice(1);
  if(battleMode){
    if(cmd==='attack'||cmd==='a'){ playerAttack(null); return; }
    if(cmd==='skill'||cmd==='cast'){ playerAttack(args.join(' ')); return; }
    if(cmd==='use'){ useItem(args.join(' ')); return; }
    if(cmd==='flee'||cmd==='f'){ tryFlee(); return; }
    if(cmd==='defend'||cmd==='守'){ playerDefend(); return; }
    if(cmd==='taunt'||cmd==='激'){ verbalAttack('taunt'); return; }
    if(cmd==='persuade'||cmd==='劝'){ verbalAttack('persuade'); return; }
    if(cmd==='reason'||cmd==='理'){ verbalAttack('reason'); return; }
    log('（战斗中可用：攻击 / 施展 武功名 / 使用 物品名 / 防御 / 激将·规劝·以理服人 嘴遁 / 逃走）','sys'); return;
  }
  const dirMap={n:'n',north:'n',s:'s',south:'s',e:'e',east:'e',w:'w',west:'w'};
  if(dirMap[cmd]){
    const r=getRoom(player.room);
    const target=r.exits[dirMap[cmd]];
    if(!target){ log('（此路不通）','sys'); return; }
    moveTo(target); return;
  }
  if(cmd==='look'||cmd==='l'||cmd==='看'){ look(); return; }
  if(cmd==='talk'||cmd==='对话'){
    if(!args.length){ log('（用法：对话 人物名）','sys'); return; }
    const who=args.join(' ');
    if(game.npcDead[who]){ log('（此人已不在人世）','sys'); return; }
    if(npcCurrentRoom(who)!==player.room){ log('（'+who+'此刻不在此处，去别处寻他吧）','sys'); return; }
    talkTo(who); return;
  }
  if(cmd==='steal'||cmd==='偷'){ if(args.length){ if(npcCurrentRoom(args.join(' '))===player.room) stealFrom(args.join(' ')); else log('（不在此处）','sys'); } else log('（用法：偷 人物名）','sys'); return; }
  if(cmd==='fight'||cmd==='战'){ if(args.length) startFight(args.join(' ')); else log('（用法：战斗 敌人名）','sys'); return; }
  if(cmd==='use'||cmd==='使用'){ if(args.length) useItem(args.join(' ')); else log('（用法：使用 物品名）','sys'); return; }
  if(cmd==='join'||cmd==='拜师'){ if(args.length) joinSect(args.join(' ')); return; }
  if(cmd==='buy'){ if(args.length){ openShop(); } return; }
  if(cmd==='rest'){ restAtInn(); return; }
  if(cmd==='heal'||cmd==='疗伤'){ healWoundAction(); return; }
  if(cmd==='looks'||cmd==='appearance'||cmd==='容装'){ openGarbPanel(); return; }
  if(cmd==='travel'||cmd==='驿'||cmd==='传送'){ if(args.length) doTravel(args.join(' ')); else openTravel(); return; }
  if(cmd==='help'||cmd==='帮助'||cmd==='?'){
    logDiv(); logTitle('—— 剑来 · 指令说明 ——');
    log('【地图】三级舆图：洲舆图点城镇入内，城镇内点建筑入内（有内部的建筑），左上「↑返回」回上一级。点地点弹出「行路」：相邻抬脚即走，远途可脚程疾行或逐格步行——移动耗时随脚力：步行两时辰/格，轻功一个时辰，骑乘坐骑只需半个时辰。','sys');
    log('【人物】下方「人物」栏点击可对话，对话后可拜师、购买、送礼、求婚等。','sys');
    log('【事件】下方「事件」栏会显示当前可触发的剧情，选项不同后果不同。','sys');
    log('【战斗】点「战 敌人」进入独立战斗场景——攻、法、守、言、走五路；环境借势（雷泽雷法大增、雪域寒刃逞威、沙海火旺水竭），嘴遁三式可破敌可退兵。','sys');
    log('【公式】气血=基础+20/级+境界与体修筑基；内力=基础+10/级+境界与练气筑基；减伤率=防御/(防御+80)，另加装备与铁布衫加成；会心=5%+0.3%/级+装备词条+暗器身法流派；暴伤默认150%，剑修辅修每层+2%。','sys');
    log('【好感】好感分五段：萍水相逢→初识→相见恨晚→肝胆相照→生死之交，越亲近越难更进一步；「谈天论道」可探心事、「旁敲侧击」可打听喜好，投其所好，事半功倍；送错东西是会恼的。','sys');
    log('【世界】江湖是活的：NPC会赶路、访友、切磋、受重伤，也会结仇寻仇；每五回合一条「江湖动态」。','sys');
    log('【奇遇】静态奇遇演尽之后，人间万象照常展开——劫道、走失、遗物、伤者、骤雨……永远有新事发生。','sys');
    log('【生成】每一档新江湖都有一把新世界种子：人物、任务、喜好各各不同；读旧档仍是旧人旧事。','sys');
    log('【技艺】「技艺」面板有四门手艺：铁匠（打造/淬炼）、炼丹（丹方/火候）、种植（需田产）、鉴宝（蒙尘物件搏机缘）——手艺越练越精。','sys');
    log('【功法】天下功法分剑法/刀法/拳掌/道法/符箓/暗器/雷法诸流派，由低而高：基础招数易得，绝学难求。','sys');
    log('【宗门】拜师入门后，掌门处可开「宗门大殿」：办宗门事务攒贡奉、以贡奉兑器物学艺、修各宗专属功课（儒门功名/佛门功德/剑道剑意/纵横军略）。宗门之间亦有交好与交恶。','sys');
    log('【功名】大骊贡院人人可考：童生→秀才→举人→进士→翰林；考中者侠名大涨，走遍天下都多三分薄面；州与州之间素来有亲疏，外乡人过境要留神。','sys');
    log('【容貌】容貌三分天生、七分打点：胭脂巷的温轻眉处可买丹换衣、授易容驻颜之术；容貌于好感有微妙助益，也会招来无赖的觊觎——以容貌周旋，也以容貌立身。','sys');
    log('【关系】侧栏「关系」可翻人情簿：结为好友可邀同游（谈天不限、嘴遁帮腔）；红颜知己可听知心话、逢难相救；恩人当记，仇人血债自有公论——好感到了，皆可变作情义。','sys');
    log('【岁月】六回合一季，二十四回合一载——四季风物轮转，顶部历法可见。通关之后，天下大事由自生成器轮番上演（妖祸、盟主大会、秘境、商路、祥瑞、灾祸、讲学、正邪论剑），可参与、可观望，皆入编年史册。','sys');
    log('【存亡】覆灭级大事件亦会降临：某宗被围、某城被攻——不救，便灭。守住了酬以威名，没守住则宗门覆灭（掌门陨落/门人四散）或城池陷落（废墟/妖兵盘踞），可在「世界大事」中筹募复兴：中兴宗门、光复城池。','sys');
    log('【财货】侧栏「财货」管着钱袋子：银两、灵石（仙家硬通货，行情随世道波动 ±），矿产行情日日不同——骊珠矿洞可下井采矿，矿石可当市价变现；灵石可灌顶修炼、淬炼保底、补复兴耗材，也能在「灵石私市」淘珍品与功法残卷。','sys');
    log('【簿册】「名望」面板可翻成就·江湖簿：初试锋芒到问鼎天下，十六桩轶事记你一路刀痕；街头不时有说书人开讲，江湖奇谈里，说不定就有你一段。','sys');
    log('【传书与运势】故人常来信：好友、红颜知己、配偶都会寄来问候（或夹带私礼），拆阅记得回信；「财货」里可花 20 两问一卦吉凶，四回合内应验于前路。','sys');
    log('【妖兽与神兽】天下妖兽、魔兽纵横，太古神兽（麒麟/朱雀/玄武/青龙/白虎/应龙/凤凰）更偶现人间——它们通灵可语，可礼敬、可立约收为灵兽，亦可硬取神兽精血；妖兽坊可买灵兽蛋孵化，衙门领妖赏、天机阁问神兽下落；侧栏「灵兽」可喂养放归。','sys');
    log('【驿路】每地都有驿站/传送阵（事件栏「驿路/传送阵」）：只通到你到访过的地方，驿费随距离与行情浮动，进士官驿折价，名正者相宜，恶名滔天者驿卒不送；也可花 1 枚灵石走传送阵直达。','sys');
    log('【家业】侧栏「家园」：置办宅邸（修养/宴客/书房）、聘管家雇家仆（产业增息、防窃）；立山头（镖局/武馆/家族/宗门）各有照应；成婚后可与配偶圆房，或有添丁之喜；子嗣六岁开蒙、十二岁可出师，资质上佳者可走天骄试炼。','sys');
    log('【恋爱与婚礼】好感与容貌到了，可「表明心意」相恋：心动→爱慕→热恋→定情，出游看月增情意；定情后便可求婚。婚后可择日大婚（家园·大婚）：简办、体面或十里红妆——来的宾客多少、贺礼厚薄，皆看往日人情；满座皆可敬酒叙话。','sys');
    log('【宗门与营生】天下八大宗门可拜（儒门·山崖书院/桐叶书院、佛门·佛光寺、剑道·落魄山/北俱剑宫、道门·龙虎山、武府·大骊武英殿、纵横·宝瓶洲渡口），各有专属修行；另有凡人的营生：泥瓶拳馆（武馆）、大骊衙门（捕快）、云来客栈镖行——僧道儒武各有各的路，狗亦有狗的道。','sys');
    log('【奇缘与流言】若与"姑姑""师父""师兄妹"这类至亲之人相恋成婚，江湖自有非议：侠名受损、恶名稍增、正道冷眼，好事者却拍案叫绝；四类流言（美谈/非议/行迹/绯闻）会在天下流传，可摆酒澄清，亦可据实认了——名望面板可见其况。','sys');
    log('【区域势力】每一州都有人管：地头蛇、文社、道派、盗团各占山头（一区或有多家）。势力之间会自行动：结盟、交恶、甚至火并吞并；「当地势力」可助势、雇探子、走内奸线，也可在火并里押一方——探子情报给你先机，暗哨会捏住你的把柄。','sys');
    log('【内应】可在「当地势力」或宗门大殿·门内手眼里策反、安插眼线：小厮、更夫、扫地僧、账房、掌勺……乃至长老、护法、大师兄、掌柜心腹，皆可为你之眼。位次分浅/中/深三档，越深越贵，也越吃你在此派的"投入"（贡奉、修行、交情）；位次越深，线报越密越准，火并、围城皆能先人一步。内应亦有忠诚，须常联络，否则一朝叛变、反噬其主。','sys');
    log('【邸报】侧栏「邸报」或直接购买/订阅：天下大事、战报、宗门动向、流言、悬赏、行情、异闻，每 12 回合出一期。单期 20 两；订一年 200 两，每期自动送达。','sys');
    log('【六维与挂机】每升一级得 2 属性点（侧栏「属性」可手动分配或洗点）：根骨(生命)、体力(内力)、智慧(经验)、敏捷(闪避脱身)、机缘(会心得宝)、魅力(好感言辞)。侧栏「自动」可开自动战斗（凌厉/稳健/保守三种打法）、自动狩猎、自动加点（浩然/纯粹武夫/练气士/剑修/读书人五种走向，散修则自行斟酌）。','sys');
    log('【年岁】时光流转，每年添一岁。少年血气未足，江湖看轻；青壮攻守俱盛，正是纵横之时；中年练达，老年、暮年气血渐衰，但智慧经验、名望之重、得宝机缘反而更厚——德高望重者，一言也抵千金。年逾花甲若未入元婴，大限将至，可服延寿丹（10 灵石）或破境求长生；转世、夺舍、元婴重塑，则从头再来。','sys');
    log('【抢亲】大婚之日，未必太平：旧爱、红颜知己，乃至宿敌恶徒，皆可能当堂来抢亲——名望压得住闲话，真感情留得住人，也有人会拔剑相向。输赢皆由好感与系统判定：赢了，婚礼照常；输了，新娘被抢、喜酒成笑话，还会传遍江湖。','sys');
    log('【江湖偶遇】行走江湖，总会撞上些戏文里的桥段：比武招亲、老翁赠书、坠崖奇遇、拍卖捡漏、英雄救美、赌坊一掷、古剑识宝、灯会猜谜、英雄帖、仙人抚顶、天降横财、仇家寻仇、乞儿报恩……机缘与凶险并存，全凭你一念之间。','sys');
    log('【闭关与行商】「自动」面板可闭关跳时：定下年月（1/3/5 年）与多件正事——修炼、行商、狩猎、产业、技艺、行善、游历，成败由系统判定，伤重自止。「商行」照大航海路数：各州特产有差价，价贱处收、价高处出，行情每回合浮动；可投资本城、积商会声望，货多了路上自有强人惦记。','sys');
    log('【宗门资源点】宗门大殿·资源点：开采独门矿石（剑胚矿、墨玉、舍利沙、雷击木……），出手换银；耗贡奉参悟本门绝学、请长老指教；护山神兽可借骑、长老可随行——都按贡奉与本钱说话。','sys');
    log('【飞升传世】修至陆地神仙（31 级）后，可在「重开」时「飞升传世」：此身全部修为、武学、社会关系将录入传世名录（永不随档消失）。新档创角时会见到名录上的故人——可选与他的前缘：其后人（承其衣钵）、门下弟子（入其师门）、捡来养大的、亲戚、街坊、路人、或干脆无关。','sys');
    log('【指令】北/南/东/西 移动 · 环顾 · 对话 人物 · 战斗 敌人 · 使用 物品 · 疗伤 · 偷 人物 · 帮助','sys');
    log('【境界】练气士与武夫两脉相承：玉璞→金身→元婴→云游→远游→金刚→指玄→天象→陆地神仙→剑修登楼→十三境→十四境→十五境。','sys');
    log('【死亡】身死后有七条生路：残魂归乡、轮回转生、元婴出窍、夺舍续命、故人相救、灵丹续命、大道眷顾。','sys');
    log('【人物】天下人物多如过江之鲫，且各有伤势际遇——重伤者可救，悬赏者可缉。「自定义人物」可亲手“写”一位江湖客入世。','sys');
    logDiv(); return;
  }
  if(cmd==='save'||cmd==='存档'){ saveGame(); return; }
  if(cmd==='load'||cmd==='读档'){ loadGame(); return; }
  if(cmd==='new'||cmd==='重开'){ askRestart(); return; }
  if(cmd==='boards'||cmd==='榜单'){ openBoards(); return; }
  if(cmd==='hunts'||cmd==='追杀令'){ openHunts(); return; }
  log('（未知指令：'+raw+'。输入「帮助」查看说明）','sys');
}

