    try{
      const node=svg.querySelector('.room-node:not(.current)');
      if(node){ node.dispatchEvent(new MouseEvent('click',{bubbles:true})); clicked=true; }
    }catch(e){}
    log('map_click_ok', clicked);
    // 结果
    const out=document.createElement('div');
    out.id='TESTREPORT';
    out.textContent=JSON.stringify(report);
    document.body.appendChild(out);
  }catch(e){
    const out=document.createElement('div');
    out.id='TESTREPORT';
    out.textContent=JSON.stringify(Object.assign(report,{FATAL:e.message}));
    document.body.appendChild(out);
  }
})();
