{"content": "// 剑来 MUD — 逻辑回归测试（无头 DOM 桩）
// 用法: node jl_logic_test.js
const fs = require('fs');
const vm = require('vm');

const html = fs.readFileSync('F:/1/jianlai/JianLai mud/index.html', 'utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if (!m) { console.log('FATAL: no script block'); process.exit(1); }
let js = m[1];

// ---------- DOM 桩 ----------
function makeEl(tag) {
  const el = {
    tagName: tag, children: [], style: {}, attrs: {}, _cls: new Set(),
    classList: {
      add: function (c) { el._cls.add(c); },
      remove: function (c) { el._cls.delete(c); },
      toggle: function (c) { if (el._cls.has(c)) { el._cls.delete(c); return false; } el._cls.add(c); return true; },
      contains: function (c) { return el._cls.has(c); }
    },
    setAttribute: function (k, v) { el.attrs[k] = String(v); },
    getAttribute: function (k) { return el.attrs[k] !== undefined ? el.attrs[k] : null; },
    appendChild: function (c) { el.children.push(c); c.parentNode = el; return c; },
    insertBefore: function (c, ref) { const i = el.children.indexOf(ref); if (i > -1) el.children.splice(i, 0, c); else el.children.push(c); return c; },
    removeChild: function (c) { const i = el.children.indexOf(c); if (i > -1) el.children.splice(i, 1); return c; },
    addEventListener: function () {},
    removeEventListener: function () {},
    querySelector: function () { return null; },
    querySelectorAll: function () { return []; },
    getBoundingClientRect: function () { return { left: 0, top: 0, width: 600, height: 400 }; },
    scrollTop: 0, scrollHeight: 0, textContent: '', innerHTML: '',
    value: '', checked: false, disabled: false,
    focus: function () {}, click: function () {},
    append: function (c) { el.children.push(c); }
  };
  Object.defineProperty(el, 'innerHTML', {
    get: function () { return el._innerHTML || ''; },
    set: function (v) { el._innerHTML = v; }
  });
  Object.defineProperty(el, 'textContent', {
    get: function () { return el._text !== undefined ? el._text : el._innerHTML || ''; },
    set: function (v) { el._text = String(v); }
  });
  return el;
}

const ids = {};
function getEl(id) {
  if (!ids[id]) ids[id] = makeEl('div');
  return ids[id];
}

const documentStub = {
  getElementById: getEl,
  createElement: function (tag) { return makeEl(tag); },
  createElementNS: function (ns, tag) { return makeEl(tag); },
  querySelector: function () { return null; },
  querySelectorAll: function () { return []; },
  body: makeEl('body'),
  documentElement: makeEl('html'),
  addEventListener: function () {},
  removeEventListener: function () {}
};
documentStub.body.classList = makeEl('div').classList;

const localStorageStub = {
  _s: {},
  getItem: function (k) { return this._s[k] !== undefined ? this._s[k] : null; },
  setItem: function (k, v) { this._s[k] = String(v); },
  removeItem: function (k) { delete this._s[k]; },
  clear: function () { this._s = {}; }
};

const windowStub = {
  addEventListener: function () {},
  removeEventListener: function () {},
  matchMedia: function () { return { addEventListener: function () {}, addListener: function () {} }; },
  location: { reload: function () {}, href: '' },
  setInterval: function () { return 1; },
  clearInterval: function () {},
  setTimeout: function () { return 1; },
  clearTimeout: function () {},
  Audio: function () { return { play: function () {}, pause: function () {}, volume: 0 }; },
  Image: function () { return {}; },
  devicePixelRatio: 1,
  innerWidth: 1280, innerHeight: 800
};
windowStub.window = windowStub;

// SVG 视图盒桩
getEl('map-svg').viewBox = { baseVal: { x: 0, y: 0, width: 1300, height: 1000 } };

const sandbox = {
  document: documentStub,
  window: windowStub,
  localStorage: localStorageStub,
  navigator: { userAgent: 'node-test' },
  console: console,
  Math: Math,
  JSON: JSON,
  Date: Date,
  Object: Object,
  Array: Array,
  String: String,
  Number: Number,
  Boolean: Boolean,
  RegExp: RegExp,
  Error: Error,
  setTimeout: function () { return 1; },
  clearTimeout: function () {},
  setInterval: function () { return 1; },
  clearInterval: function () {},
  parseInt: parseInt,
  parseFloat: parseFloat,
  isNaN: isNaN,
  isFinite: isFinite,
  undefined: undefined
};
sandbox.globalThis = sandbox;
vm.createContext(sandbox);

// 测试代码（与游戏脚本同作用域）
const testCode = `
(function(){
  const report = {};
  const log = (k, v) => { report[k] = v; };
  try {
    freshGame();
    player.room = '泥瓶巷';
    player.visited = ['泥瓶巷'];
    game.mapLevel = 'cheng';
    game.cheng = 'cheng_lizhu';
    game.bld = null;

    // ===== Fix3: 网格布局引擎 =====
    const L = computeGridLayout();
    log('grid_key', L.key);
    log('grid_w_h', L.w + 'x' + L.h);
    log('grid_nodes', Object.keys(L.pos).length);
    // 所有本层房间都有坐标
    let missing = [];
    for (const rn in ROOMS) {
      if (ROOMS[rn].area === 'cheng_lizhu' && typeof ROOMS[rn].bld !== 'string') {
        if (!L.pos[rn]) missing.push(rn);
      }
    }
    log('grid_missing_pos', missing.length);
    log('grid_first3', JSON.stringify(Object.keys(L.pos).slice(0, 3).map(k => k + ':' + L.pos[k].x + ',' + L.pos[k].y)));

    // 连线横平竖直检查：随机取若干边，路径只含水平/垂直段
    const svg = document.getElementById('map-svg');
    renderChengMap(svg, false);
    const paths = svg.children.filter(c => c.tagName === 'path');
    log('cheng_paths', paths.length);
    const rects = svg.children.filter(c => c.tagName === 'rect');
    log('cheng_rects', rects.length);
    // 正交性：每条 path 的 d 应只含 H/V 命令（或单段直线）
    let nonOrtho = 0;
    paths.forEach(p => {
      const d = p.attrs.d || '';
      if (d && !/^M[^HVL]*$/.test(d)) {
        const segs = d.match(/[HVL]/g) || [];
        const bad = segs.filter(s => s === 'L').length;
        // 允许 M x y L x y 的单段直线（同行），但不允许对角 L
        if (/ L/.test(d) && !/^M[^ ]+ [^ ]+ L[^ ]+ [^ ]+$/.test(d)) nonOrtho++;
      }
    });
    log('cheng_non_ortho', nonOrtho);

    // zhou 层
    game.mapLevel = 'zhou'; game.cheng = null; game.bld = null;
    player.room = 'cheng_lizhu';
    const Lz = computeGridLayout();
    log('zhou_nodes', Object.keys(Lz.pos).length);
    log('zhou_w_h', Lz.w + 'x' + Lz.h);
    const svg2 = document.getElementById('map-svg');
    renderZhouMap(svg2);
    log('zhou_paths', svg2.children.filter(c => c.tagName === 'path').length);
    log('zhou_rects', svg2.children.filter(c => c.tagName === 'rect').length);

    // nei 层
    game.mapLevel = 'cheng'; game.cheng = 'cheng_lizhu'; game.bld = null;
    player.room = '骊珠小镇·平安客栈';
    game.mapLevel = 'nei'; game.bld = '骊珠小镇·平安客栈'; game.cheng = 'cheng_lizhu';
    const Ln = computeGridLayout();
    log('nei_nodes', Object.keys(Ln.pos).length);
    const svg3 = document.getElementById('map-svg');
    renderChengMap(svg3, true);
    log('nei_paths', svg3.children.filter(c => c.tagName === 'path').length);

    // ===== Fix1: 四向移动 =====
    game.mapLevel = 'cheng'; game.bld = null; game.cheng = 'cheng_lizhu';
    player.room = '泥瓶巷';
    const r0 = getRoom(player.room);
    const dirs = ['n','s','e','w'].filter(d => r0.exits && r0.exits[d]);
    log('move_dirs_avail', dirs.join(','));
    if (dirs.length) {
      const before = player.room;
      moveDir(dirs[0]);
      log('moveDir_moved', player.room !== before);
      log('moveDir_room', player.room);
    }
    // 无路方向
    player.room = '泥瓶巷';
    const blocked = ['n','s','e','w'].filter(d => !(r0.exits && r0.exits[d]));
    if (blocked.length) {
      const before = player.room;
      moveDir(blocked[0]);
      log('moveDir_blocked_ok', player.room === before);
    }

    // ===== Fix2: 行囊/疗伤/调养 =====
    addItem('疗伤丹'); addItem('柳木剑');
    player.hp = Math.floor(player.maxHp / 2);
    const hpBefore = player.hp;
    openBackpack();
    log('backpack_modal', !!document.getElementById('modal'));
    document.getElementById('overlay').classList.remove('show');
    player.wound = 1;
    addItem('疗伤丹');
    healAction();
    log('heal_reduced_wound', player.wound === 0);
    player.hp = Math.floor(player.maxHp / 2);
    restAction();
    log('rest_restored', player.hp >= hpBefore);

    log('RESULT_OK', true);
  } catch (e) {
    log('FATAL', e && e.stack ? e.stack.split('\\n').slice(0, 4).join(' | ') : String(e));
  }
  const out = JSON.stringify(report);
  fs.writeFileSync('F:/1/jl-test/logic-report.json', out, 'utf8');
  console.log('REPORT: ' + out);
})();
`;

try {
