    log('zhou_w_h', Lz.w + 'x' + Lz.h);
    const svg2 = document.getElementById('map-svg');
    renderZhouMap(svg2);
    log('zhou_paths', svg2.children.filter(c => c.tagName === 'path').length);
    log('zhou_rects', svg2.children.filter(c => c.tagName === 'rect').length);

    // nei 层
    game.mapLevel = 'cheng'; game.cheng = 'cheng_lizhu'; game.bld = null;
    player.room = '骊珠小镇·平安客栈';
    game.mapLevel = 'nei'; game.bld = '骊珠小镇·平安客栈'; game.cheng = 'cheng_lizhu';
    const Ln = computeGridLayout();
    log('nei_nodes', Object.keys(Ln.pos).length);
    const svg3 = document.getElementById('map-svg');
    renderChengMap(svg3, true);
    log('nei_paths', svg3.children.filter(c => c.tagName === 'path').length);

    // ===== Fix1: 四向移动 =====
    game.mapLevel = 'cheng'; game.bld = null; game.cheng = 'cheng_lizhu';
    player.room = '泥瓶巷';
    const r0 = getRoom(player.room);
    const dirs = ['n','s','e','w'].filter(d => r0.exits && r0.exits[d]);
    log('move_dirs_avail', dirs.join(','));
    if (dirs.length) {
      const before = player.room;
      moveDir(dirs[0]);
      log('moveDir_moved', player.room !== before);
      log('moveDir_room', player.room);
    }
    // 无路方向
    player.room = '泥瓶巷';
    const blocked = ['n','s','e','w'].filter(d => !(r0.exits && r0.exits[d]));
    if (blocked.length) {
      const before = player.room;
      moveDir(blocked[0]);
      log('moveDir_blocked_ok', player.room === before);
    }

    // ===== Fix2: 行囊/疗伤/调养 =====
    addItem('疗伤丹'); addItem('柳木剑');
    player.hp = Math.floor(player.maxHp / 2);
    const hpBefore = player.hp;
    openBackpack();
    log('backpack_modal', !!document.getElementById('modal'));
    document.getElementById('overlay').classList.remove('show');
    player.wound = 1;
    addItem('疗伤丹');
    healAction();
    log('heal_reduced_wound', player.wound === 0);
    player.hp = Math.floor(player.maxHp / 2);
    restAction();
    log('rest_restored', player.hp >= hpBefore);

    log('RESULT_OK', true);
  } catch (e) {
    log('FATAL', e && e.stack ? e.stack.split('\\n').slice(0, 4).join(' | ') : String(e));
  }
  const out = JSON.stringify(report);
  fs.writeFileSync('F:/1/jl-test/logic-report.json', out, 'utf8');
  console.log('REPORT: ' + out);
})();
`;

