    const svg = document.getElementById('map-svg');
    renderChengMap(svg, false);
    const allEls = [];
    (function collect(els) { els.forEach(e => { allEls.push(e); if (e.children) collect(e.children); }); })(svg.children);
    const paths = allEls.filter(c => c.tagName === 'path');
    log('cheng_paths', paths.length);
    const rects = allEls.filter(c => c.tagName === 'rect');
    log('cheng_rects', rects.length);
    // 正交性：解析路径的每个 L 段，检查是水平或垂直
    let nonOrtho = 0;
    paths.forEach(p => {
      const d = p.attrs.d || '';
      if (!d) return;
      const nums = d.match(/-?\d+(\.\d+)?/g).map(Number);
      // M x0 y0 L x1 y1 L x2 y2 ...
      let cx = nums[0], cy = nums[1];
      for (let i = 2; i + 1 < nums.length; i += 2) {
        const nx = nums[i], ny = nums[i + 1];
        if (cx !== nx && cy !== ny) nonOrtho++;
        cx = nx; cy = ny;
      }
    });
    log('cheng_non_ortho', nonOrtho);", "old_string": "    // 连线横平竖直检查：随机取若干边，路径只含水平/垂直段
