//    水到渠成 / 丹药 / 灌顶 / 感悟 / 顿悟，五途任选。
function realmIndexByLevel(){ let i=0; for(let r=1;r<REALMS.length;r++){ if(player.level>=REALMS[r].lv) i=r; } return i; }
function realmIndex(){
  if(typeof player.realm==='number') return Math.max(0, Math.min(player.realm, REALMS.length-1));
  return realmIndexByLevel(); // 旧档兜底：无 realm 字段时按等级推算
}
function nextRealmIdx(){
  const cur=realmIndex();
  return (cur+1<REALMS.length)?cur+1:-1;
}
function realmBottleneck(){
  // 等级已够、境界未破 → 卡在瓶颈，可破境
  const nx=nextRealmIdx();
  if(nx<0) return -1;
  return (player.level>=REALMS[nx].lv)?nx:-1;
