// —— 触发主线剧情节点（chapter 推进时调用） ——
function playChapterBeat(c){
  const beat=CHAPTER_BEATS.find(function(b){ return b.chapter===c && !(game.beats&&game.beats[b.key]); });
  if(!beat) return;
  if(!game.beats) game.beats={};
  const h=document.createElement('div');
  h.style.cssText='font-size:.82em;color:#ffffff;';
  const who=document.createElement('div'); who.style.cssText='color:var(--gold-bright);letter-spacing:2px;margin-bottom:8px;';
  who.textContent='◆ 主线 · '+beat.title+(beat.who?'　—— '+beat.who:'');
  h.appendChild(who);
  beat.lines.forEach(function(l){
    const p=document.createElement('p'); p.style.cssText='line-height:1.9;margin:6px 0;color:#ffffff;';
    p.textContent=l; h.appendChild(p);
  });
  const pick=document.createElement('div'); pick.style.cssText='margin-top:10px;border-top:1px solid var(--line-soft);padding-top:8px;';
  const lbl=document.createElement('div'); lbl.style.cssText='color:#c9c9cf;font-size:.72em;letter-spacing:2px;margin-bottom:6px;'; lbl.textContent='—— 你的选择 ——';
  pick.appendChild(lbl);
  beat.options.forEach(function(o,i){
    if(o.req && !o.req()) return;
    const b=document.createElement('button'); b.className='btn'; b.style.cssText='display:block;width:100%;margin:4px 0;padding:8px;text-align:left;font-size:.8em;';
    b.textContent=(i+1)+'. '+o.text;
    b.addEventListener('click',function(){
      game.beats[beat.key]=true;
      document.getElementById('overlay').classList.remove('show');
      o.effect();
      updateSidebar(); renderMap();
      logDiv();
    });
    pick.appendChild(b);
  });
  h.appendChild(pick);
  openModal('主线 · '+chapterName(), ()=>h);
