// —— 敌人特性说明（战斗开场展示） ——
function traitLine(trait){
  if(!trait) return '';
  const T={
    pack:'狼群习性：同伴愈少，攻势愈狂',
    brute:'蛮力：攻势沉重，受伤后愈发狂暴',
