    frenzy:'狂性：气血越低，攻击越猛',
    poison:'剧毒：利爪带毒，久战必中毒',
    berserk:'悍不畏死：濒死时爆发最后凶威',
    fire:'火属妖力：烈焰灼人，越战越炽',
    immortal:'渊渟岳峙：力大防厚，愈战愈强',
    constrict:'绞杀：缠住对手，令其难以脱身',
    undead:'不死：白骨之躯，愈战愈坚',
    lightning:'雷属：电光石火，出手极快',
    thief:'诡诈：善于偷袭，防不胜防',
    demon:'魔气：攻势附带魔焰，伤魂蚀骨',
    armored:'铁甲：皮糙肉厚，防御惊人',
    ice:'寒冰：吐息冰封，令动作迟缓',
    soul:'摄魂：夺人心神，令人恍惚',
    holy:'祥瑞威压：浩然之气，攻防兼备',
    iron:'玄武之躯：万古不移，难以撼动',
    thunder:'风雷随行：雷霆之怒，速攻兼备',
    feral:'庚金杀伐：爪牙如刀，会心极高',
    divine:'龙威如狱：上古龙威，威压众生',
    rebirth:'浴火重生：濒死之际，涅槃复原'
  };
  return T[trait]||'';
}
// —— BOSS 阶段判定（按气血比例触发台词与增益） ——
function checkBossPhase(){
  if(!battle || !battle.phase) return;
  const hpR=battle.hp/battle.maxHp;
  const keys=Object.keys(battle.phase).map(Number).sort(function(a,b){return b-a;});
  for(let i=0;i<keys.length;i++){
    const pct=keys[i];
    if(hpR<=pct && !battle.phaseTriggered[pct]){
      battle.phaseTriggered[pct]=true;
      battleLog(battle.phase[pct],'boss');
      // 阶段增益：气血愈低，攻愈狂（BOSS 的"多阶段"）
      battle.atk=Math.round(battle.atk*1.12);
      if(battle.trait==='iron'||battle.trait==='immortal') battle.def=Math.round(battle.def*1.15);
      if(battle.trait==='rebirth' && pct===keys[keys.length-1] && !battle.rebirthUsed){
        // 凤凰涅槃：接近死亡时浴火复原一次
        battle.rebirthUsed=true;
        battle.hp=Math.round(battle.maxHp*0.55);
        battleLog('（凤凰长唳，浴火重生——'+(battle.name)+'的伤势竟以肉眼可见的速度复原！）','boss');
        renderBattleOverlay();
      }
      return; // 一回合只触发一阶段
    }
  }
}
// —— 敌人特性效果（敌方行动时结算） ——
function enemyTraitEffects(){
  if(!battle) return;
  const t=battle.trait;
  if(!t) return;
  const hpR=battle.hp/battle.maxHp;
  // 剧毒：我方中毒（沙蝎/双头蛇）
  if(t==='poison' && Math.random()<0.3){
    battle.poison=Math.max(battle.poison,2);
    battleLog('（你被'+(battle.name)+'的毒爪划伤——毒素入体！）','combat');
  }
  // 摄魂：噬魂魔蝶夺我心神（内力流失）
  if(t==='soul' && Math.random()<0.25){
    const loss=Math.min(player.mp, Math.round(effMaxMp()*0.1));
    player.mp-=loss;
    battleLog('（'+(battle.name)+'翅上的花纹摄人心魄——内力 -'+loss+'！）','combat');
  }
  // 寒冰：吐息减速（我方攻方略减）
  if(t==='ice' && battle.hp/battle.maxHp<0.7 && Math.random()<0.3){
    battleLog('（刺骨寒潮扑面——你的攻势为之一滞！）','info');
  }
  // 狼群/狂性/蛮力/悍不畏死：低血加攻（战斗中实时体现）
  if((t==='pack'||t==='frenzy'||t==='brute'||t==='berserk') && hpR<0.4 && !battle.bloodAtk){
    battle.bloodAtk=true;
    battle.atk=Math.round(battle.atk*1.25);
    battleLog('（'+(battle.name)+'见血愈狂，攻势暴涨！）','boss');
  }
}
// —— 敌人掉落（战后结算） ——
function enemyLoot(){
  if(!battle || !battle.lootTable || !battle.lootTable.length) return;
  const luck=attrLootLuck();
  const n=1+(Math.random()<0.3?1:0);
  let got=0;
  for(let i=0;i<n && i<battle.lootTable.length;i++){
    if(Math.random()<Math.min(0.9,0.45+luck)){
      const it=battle.lootTable[Math.floor(Math.random()*battle.lootTable.length)];
      addItem(it);
      battleLog('（从'+(battle.name)+'身上搜得：'+it+'）','item');
      got++;
    }
  }
  return got;
