{"file_path": "F:\1\jianlai\JianLai mud\index.html", "new_string": "function enemyTurn(){
  if(!battle || battle.hp<=0) return;
  battle.enemyActed=true; // 敌方已出手（斩风先手判定用）
  if(battle.env.mpRegen>0 && player.mp<effMaxMp()){
    const reg=Math.min(battle.env.mpRegen, effMaxMp()-player.mp);
    player.mp+=reg;
    battleLog('（'+battle.env.name+'的灵气缓缓入体，内力 +'+reg+'。）','info');
  }
  // 剧毒发作：毒素持续掉血（沙蝎/双头蛇）
  if(battle.poison>0){
    battle.poison--;
    const pdmg=Math.max(1, Math.round(battle.atk*0.18));
    player.hp-=pdmg;
    updateWound();
    battleLog('（毒性发作——你受到 '+pdmg+' 点毒素伤害！'+(battle.poison>0?'毒素仍在体内翻涌。':'毒素渐散。')+'）','combat');
    if(player.hp<=0){ onPlayerDown(); return; }
  }
  enemyTraitEffects(); // 敌人特性（剧毒/摄魂/狂化……）
  // —— 公式结算：敌方攻击力 → 我方减伤（守御额外） → 敌方会心 → 浮动 ——
  let aMul=battle.env.enAtk||1;
  if(battle.fear>0){ battle.fear--; aMul*=FORMULAS.fearAtkMul; if(battle.fear===0) battle.controlStreak=0; }
  const power=Math.max(1, Math.floor(battle.atk*aMul));
  let red=dmgReduction();
  if(battle.myGuard){ red+=FORMULAS.guardSoften; battle.myGuard=false; }
  red=Math.min(0.85, red);
  let edmg=Math.max(1, Math.floor(power*(1-red)));
  if(Math.random()<enemyCritRate(battle.lvl)){
    edmg=Math.max(1, Math.floor(edmg*FORMULAS.enemyCritDmg));
  }
  // 敌人特性：寒渊吐息令攻势迟滞（敌方回合内我方下一击略弱，此处以扣蓝呈现）
  if(battle.trait==='ice' && Math.random()<0.15 && player.mp>3){
    player.mp-=3;
    battleLog('（寒气侵体，你体内经脉一阵凝滞——内力 -3。）','info');
  }
  // 幽魂飘忽：闪避敌方普攻（阴鬼）
  if(battle.trait==='ghost' && Math.random()<0.18){
    battleLog('（'+battle.name+'身形忽隐忽现，你这一记落了个空！）','sys');
    battle.taunt=Math.max(0,battle.taunt-1);
    renderBattleOverlay(); updateSidebar();
    return; // 敌方闪避后不再反击（节奏更紧凑）
  }
  const ev=Math.floor(Math.random()*3)-1;
  edmg=Math.max(1, edmg+ev);
  if(Math.random()<attrDodge()){ // 敏捷：身法如电
    battleLog('（你身形一晃，'+(battle.name)+'的攻击擦着衣角落了个空！）','skill');
  } else {
    player.hp-=edmg;
    updateWound();
    battleLog('「'+battle.name+'」反击，你受到 '+edmg+' 点伤害'+(battle.fear>0?'（其势已怯，力有不逮）':'')+'！','combat');
  if(player.hp>0 && player.hp/effMaxHp()<FORMULAS.desperateHp && !battle.flairUsed.lowSelf){ battle.flairUsed.lowSelf=true; battleLog(flair('lowSelf'),'sys'); }
  }
  if(battle.taunt>0) battle.taunt--;
  if(player.hp<=0){ onPlayerDown(); return; }
  renderBattleOverlay();
  updateSidebar();
