      if(Math.random()<0.4){ const it=jp(['洞天玉简','灵石','仙家雪莲','九转金丹','玄铁']); addItem(it); logSuccess('（你循图掘地三尺，竟真挖出一件「'+it+'」！五十两，值了！）'); }
