    {text:'帮村民淘井', desc:'与人方便，自己方便', fn:function(){ gainFame(3); player.exp+=25; logSuccess('（你跳下井帮村民清淤——井水重见天日，乡亲们塞给你一篮鸡蛋。名望 +3，经验 +25。）'); }},
