    {text:'坐下来，听他说完', desc:'自己的故事，自己听', fn:function(){ gainFame(3); gainRealize(4); logSuccess('（说书先生把你夸成了一朵花——虽然添油加醋，听着倒也受用。名望 +3，感悟 +4。）'); }},
    {text:'打赏一壶好茶，请他细说', desc:'捧个人场', fn:function(){ player.gold-=5; gainFame(5); logSuccess('（你打赏得阔气，说书先生讲得更起劲——满堂人都记住了你的名号。名望 +5。）'); }},
    {text:'揭穿他说错了，转身离开', desc:'江湖事，当真不得', fn:function(){ logInfo('（你撇撇嘴：那件事我干得可比他说的漂亮多了。众人目送你出门，交头接耳。）'); gainFame(1); }}
   ]},
  {id:'blacksmithGuest', title:'铁匠的旧友', weight:2,
   text:function(){ return '铁匠铺的炉火正旺，一位满脸风霜的江湖客倚在门口，手里摩挲着一柄断刀："老伙计，还认得这把刀么？"'; },
   options:[
    {text:'驻足听他们的江湖旧事', desc:'一把旧刀，半生江湖', fn:function(){ player.exp+=35; logInfo('（铁匠与旧友说起当年并肩闯荡的往事——你听得入神。经验 +35。）'); }},
    {text:'买下那柄断刀', desc:'断刀虽残，亦是故人', fn:function(){ if(player.gold<30){ log('（你囊中羞涩，铁匠的旧友摆手道：罢了罢了。）','sys'); return; } player.gold-=30; addItem('断刀'); logSuccess('（你花了 30 两买下断刀——那江湖客朝你一抱拳：小友，谢了。获得「断刀」。）'); }},
    {text:'请铁匠帮忙看看你的兵刃', desc:'磨刀不误砍柴工', fn:function(){ const eq=player.equipment.weapon; if(!eq){ log('（你摊开手：兵刃还没有着落。）','sys'); return; } logSuccess('（铁匠三锤两斧，把你的「'+itemLabel(eq)+'」拾掇得趁手了些——攻击 +2。）'); player.atk+=2; }}
   ]},
  {id:'phoenixKite', title:'纸鸢纷飞', weight:1,
   text:function(){ return '春风十里，满天的纸鸢。一个扎纸鸢的姑娘站在田埂上，手里那只凤凰纸鸢却怎么也飞不起来——她急得直跺脚。'; },
   options:[
    {text:'帮她调整纸鸢，教她放线', desc:'助人一臂之力', fn:function(){ gainFame(2); if(Math.random()<0.3){ gainAff(pickFemaleNpc(),4); logSuccess('（纸鸢终于扶摇直上——姑娘笑靥如花，说要给她认识的姐妹们讲讲你的好话。名望 +2。）'); } else { logSuccess('（纸鸢飞起来了！姑娘追着它跑出好远——你这一日，心里也轻快。名望 +2。）'); } }},
    {text:'买下那只凤凰纸鸢', desc:'纸鸢虽小，也是缘分', fn:function(){ player.gold-=5; player.exp+=15; logInfo('（你把纸鸢挂在行囊上——风一来，它便轻轻振翅。经验 +15。）'); }},
    {text:'指点她风向不对', desc:'纸上谈兵', fn:function(){ logInfo('（姑娘将信将疑地换了方向——纸鸢果然飞了起来！她惊喜地回头看你，你却已走出老远。）'); gainFame(1); }}
   ]},
  {id:'strayCat', title:'拦路的小猫', weight:1,
   text:function(){ return '一只黑白花的小猫蹲在路中央，圆溜溜的眼睛盯着你，尾巴轻轻摇——仿佛在等你开口。'; },
   options:[
    {text:'蹲下逗它', desc:'猫有猫的缘分', fn:function(){ if(Math.random()<0.25){ player.lingStone=(player.lingStone||0)+1; logSuccess('（小猫蹭了蹭你的手，忽然叼起一枚亮晶晶的石头放在你脚边——竟是灵石！+1。）'); } else { logInfo('（小猫绕着你转了两圈，"喵"了一声，转身钻进了巷子——像是一场小小的告别。）'); } }},
    {text:'喂它一点干粮', desc:'有缘千里来相会', fn:function(){ if(hasItem('干粮')){ removeItem('干粮'); gainRealize(4); logSuccess('（小猫吃得香，尾巴翘得老高——你看着，心里也暖了。感悟 +4。）'); } else { logInfo('（你翻遍行囊也没找到吃的——小猫失望地走开了。）'); } }},
    {text:'不理会，径直走过', desc:'江湖路远，各走一边', fn:function(){ logInfo('（你大步走过——身后传来一声轻软的"喵"，像在说：后会有期。）'); }}
   ]},
  {id:'drunkSwordsman', title:'醉剑客', weight:2,
   text:function(){ return '酒肆里，一个醉醺醺的剑客趴在桌上，手边一坛见底的酒，嘴里含糊不清地念叨着剑诀。店家正发愁怎么打发他。'; },
   options:[
    {text:'替他付了酒钱', desc:'同是江湖人', fn:function(){ player.gold-=5; if(Math.random()<0.35){ const sk=jp(['泼墨剑法','星光剑法','崩山拳']); learnSkill(sk); logSuccess('（醉剑客忽然睁眼，抓住你的手："酒钱……不白收！"——你稀里糊涂学了一门「'+sk+'」！）'); } else { gainRealize(5); logSuccess('（醉剑客晃晃悠悠地站起来，朝你一抱拳，出门去了。感悟 +5。）'); } }},
    {text:'抢过酒坛，陪他一醉', desc:'酒逢知己千杯少', fn:function(){ if(Math.random()<0.4){ player.exp+=45; logSuccess('（两人对饮到天明——醉剑客口吐真言，把半生剑理都倒给了你。经验 +45。）'); } else { player.mp=Math.min(effMaxMp(), player.mp+Math.round(effMaxMp()*0.1)); logInfo('（你俩都喝趴了——醒来时，醉剑客已不知去向，只留一坛好酒在你枕边。内力 +10%。）'); } }},
    {text:'叫店家把他扔出去', desc:'酒鬼碍事', fn:function(){ log('（店家千恩万谢——那醉剑客被架出去时，嘴里还在念叨："我的剑……我的剑……"）','sys'); }}
   ]},
  {id:'medicineWell', title:'枯井灵泉', weight:2, cond:function(){ return player.hp<player.maxHp; },
   text:function(){ return '村口一口枯井，井边围了几个村民唉声叹气。你探头一看——井底竟渗出丝丝清泉，隐隐有灵气升腾。'; },
   options:[
    {text:'下井取水，试饮灵泉', desc:'枯井生泉，或有奇效', fn:function(){ player.hp=Math.min(player.maxHp, player.hp+Math.round(player.maxHp*0.3)); player.wound=Math.max(0,player.wound-1); logSuccess('（灵泉入喉，如饮甘霖——气血恢复 30%，伤势也舒缓了些！）'); }},
    {text:'帮村民淘井', desc:'与人方便，自己方便', fn:function(){ gainFame(3); player.exp+=25; logSuccess('（你跳下井帮村民清淤——井水重见天日，乡亲们塞给你一篮鸡蛋。名望 +3，经验 +25。）'); }},
    {text:'取一瓶泉水带走', desc:'带回家慢慢喝', fn:function(){ addItem('灵泉水'); logSuccess('（你灌了一壶灵泉——获得「灵泉水」。）'); }}
   ]},
  {id:'chessOldMan', title:'棋摊老人', weight:2,
   text:function(){ return '城墙根下，一位老人摆着棋摊，残局未竟，落子如飞。他见你驻足，头也不抬："会下棋么？来，陪老头子杀一局。"'; },
   options:[
    {text:'坐下对弈', desc:'棋如人生，落子无悔', fn:function(){ const zh=attrV('zhihui'); const chance=Math.min(0.9,0.35+zh*0.02+player.level*0.01);
      if(Math.random()<chance){ gainFame(3); player.exp+=35; logSuccess('（你以'+(zh||0)+'点悟性布子，竟赢了半目——老人抚掌而笑："好棋！"名望 +3，经验 +35。）'); }
      else { gainRealize(6); logInfo('（你中盘告负——老人随手点了你几处疏漏，句句在理。感悟 +6。）'); } }},
    {text:'花十两学一局', desc:'拜师学艺', fn:function(){ if(player.gold<10){ log('（你摸遍口袋——老人摆摆手：没钱也能看。）','sys'); return; } player.gold-=10; gainRealize(8); player.exp+=25; logSuccess('（老人耐心教你拆解残局——虽花去 10 两，却受用无穷。经验 +25，感悟 +8。）'); }},
    {text:'观棋不语', desc:'做个安静的看客', fn:function(){ logInfo('（你在旁看了一下午——棋声清脆，日光西斜。心境不知不觉静了下来。感悟 +4。）'); gainRealize(4); }}
   ]},
  {id:'travellingMerchant', title:'行商遇袭', weight:2,
   text:function(){ return '官道旁，一队行商的车马被几个蒙面人围住，为首的大声吆喝着"留下买路财！"商队护卫已倒下一人，情势危急。'; },
   options:[
    {text:'拔刀相助，击退劫匪', desc:'路见不平（恶战）', cls:'primary', fn:function(){ logBoss('（你纵身跃入战圈——蒙面人见来了硬茬，为首的一挥手："一起上！"）'); tropeFight({name:'蒙面劫匪', tropeId:'travellingMerchant', hp:85+player.level*20, atk:23+player.level*2, def:9+player.level, exp:75, goldMin:35, goldMax:85}); }},
    {text:'高声呼喊"官兵来了"', desc:'虚张声势', fn:function(){ if(Math.random()<0.5){ gainFame(4); logSuccess('（你这一嗓子中气十足——劫匪们信以为真，一哄而散！商队首领千恩万谢。名望 +4。）'); } else { log('（劫匪头子冷笑："官兵？这条路，归我们管。"——一场恶战难免！）','warn'); tropeFight({name:'蒙面劫匪', tropeId:'travellingMerchant', hp:85+player.level*20, atk:23+player.level*2, def:9+player.level, exp:75, goldMin:35, goldMax:85}); } }},
    {text:'悄悄绕行，事不关己', desc:'明哲保身', fn:function(){ logInfo('（你低下头，从灌木丛后绕了过去——身后兵刃碰撞声渐远，你心里却像压了块石头。）'); }}
   ]},
  {id:'bambooForest', title:'竹林琴音', weight:1,
   text:function(){ return '竹林深处，一缕琴音如流水淌出。弹琴人背对你坐在石上，琴声里似有千般愁绪，又似万古从容。'; },
   options:[
    {text:'驻足听琴，直到曲终', desc:'知音难得', fn:function(){ gainRealize(10); player.mp=Math.min(effMaxMp(), player.mp+Math.round(effMaxMp()*0.1)); logSuccess('（一曲终了，弹琴人朝你微微颔首，飘然离去——你久久立于竹下。内力 +10%，感悟 +10。）'); }},
    {text:'以剑和之，琴剑相鸣', desc:'以武会友', fn:function(){ if(Math.random()<0.4){ player.exp+=50; gainRealize(6); logSuccess('（琴剑相和，竟有几分天人合一的味道——经验 +50，感悟 +6。）'); } else { logInfo('（琴音一顿，弹琴人摇摇头——你的剑意，还差一点"静"。感悟 +4。）'); gainRealize(4); } }},
    {text:'不打扰，悄然离开', desc:'风过竹林，了无痕', fn:function(){ logInfo('（你轻手轻脚地走了——琴音依旧，仿佛你从未出现过。）'); }}
   ]},
