    {text:'高声叫好，添些热闹', desc:'看客也有看客的江湖', fn:function(){ gainFame(1); logInfo('（你这一嗓子喊得响亮，胜者朝你拱了拱手——江湖人，敬的是懂行的看客。名望 +1。）'); }}
   ]},
  {id:'lostMap', title:'残缺藏宝图', weight:1,
   text:function(){ return '一个江湖郎中拉住你，神秘兮兮地亮出一张边角泛黄的羊皮："此图所指，埋着一桩大机缘——五十两，归你了！"'; },
   options:[
    {text:'买下藏宝图，依图寻宝', desc:'五十两搏一场富贵', fn:function(){ if(player.gold<50){ log('（你摸遍口袋，凑不出五十两——郎中摇头叹息。）','sys'); return; } player.gold-=50;
      if(Math.random()<0.4){ const it=jp(['洞天玉简','灵石','仙家雪莲','九转金丹','玄铁']); addItem(it); logSuccess('（你循图掘地三尺，竟真挖出一件「'+it+'」！五十两，值了！）'); }
