   ]},
  {id:'hermitTea', title:'山野茶寮', weight:2,
   text:function(){ return '山道边的野茶寮里，一个白眉老者正慢条斯理地煮茶，茶香混着松风，格外清冽。他见你落座，也不言语，只推过一盏茶。'; },
   options:[
    {text:'饮下这盏茶，静心片刻', desc:'山中一盏茶，可抵十年尘', fn:function(){ player.mp=Math.min(effMaxMp(), player.mp+Math.round(effMaxMp()*0.2)); gainRealize(8); logSuccess('（一盏清茶入喉，连日风尘竟一扫而空——内力 +20%，感悟 +8。）'); }},
    {text:'与老者论茶论道', desc:'以茶会友', fn:function(){ if(Math.random()<0.4){ player.exp+=40; gainRealize(6); logSuccess('（老者三言两语，竟句句切中你修行关窍——经验 +40，感悟 +6。）'); } else { gainRealize(10); logInfo('（你听老者讲了半日茶经，虽未得修为，心境却澄澈了许多。感悟 +10。）'); } }},
    {text:'问老者名号', desc:'高人隐于野', fn:function(){ logInfo('（老者一笑："山野之人，名字早被风吹散了。"——言罢，茶寮竟如雾散，唯余一盏残茶。）'); player.exp+=25; }}
   ]},
  {id:'duelWatch', title:'剑客约战', weight:2,
   text:function(){ return '前方一片空地上，两名剑客相对而立，风过衣袂猎猎。围观者屏息——这是要在江湖上分个高下的约战！'; },
   options:[
    {text:'驻足观战，偷学剑意', desc:'看高人过招，胜过十年苦修', fn:function(){ if(Math.random()<0.35){ player.exp+=60; gainRealize(8); logSuccess('（双剑交错，你隐约抓住一线剑意——经验 +60，感悟 +8。）'); } else { player.exp+=25; logInfo('（剑光太快，你看得目眩——只记下了几个起手。经验 +25。）'); } }},
    {text:'下场挑战胜者', desc:'一战成名（硬仗）', cls:'primary', fn:function(){ logBoss('（胜者剑锋一转，指向了你："还有不怕死的？"——全场哗然！）'); tropeFight({name:'约战剑客', tropeId:'duelWatch', hp:100+player.level*24, atk:27+player.level*2, def:11+player.level, exp:95, goldMin:45, goldMax:110}); }},
    {text:'高声叫好，添些热闹', desc:'看客也有看客的江湖', fn:function(){ gainFame(1); logInfo('（你这一嗓子喊得响亮，胜者朝你拱了拱手——江湖人，敬的是懂行的看客。名望 +1。）'); }}
   ]},
  {id:'lostMap', title:'残缺藏宝图', weight:1,
   text:function(){ return '一个江湖郎中拉住你，神秘兮兮地亮出一张边角泛黄的羊皮："此图所指，埋着一桩大机缘——五十两，归你了！"'; },
