{"file_path": "F:\1\jianlai\JianLai mud\index.html", "new_string": "let _clockTimer=null, _saveTimer=null; // 时钟 / 自动存档定时器（进世界后启动，避免重复）

/* ================================================================
   框架核心 · 心跳 Daemon（仿 MUDCore heart_beat）
   —— 所有周期任务统一注册到 HEART，由单一心跳驱动：
      时钟 / 自动存档 / 音乐 / 世界静默推进……
      取代散落的 setInterval，便于统一启停与调度。
   ================================================================ */
const HEART={
  _timer:null, _beats:{},
  // 注册周期任务：beat(name, ms, fn) —— 到点执行 fn
  beat:function(name, ms, fn){
    this._beats[name]={ms:ms, fn:fn, acc:0};
    return name;
  },
  // 注销任务
  unbeat:function(name){ delete this._beats[name]; },
  // 启动心跳（幂等）
  start:function(){
    if(this._timer) return;
    const self=this;
    this._timer=setInterval(function(){ self._tick(); }, 1000);
  },
  // 停止心跳
  stop:function(){
    if(this._timer){ clearInterval(this._timer); this._timer=null; }
  },
  _tick:function(){
    for(const k in this._beats){
      const b=this._beats[k];
      b.acc+=1000;
      if(b.acc>=b.ms){
        b.acc=0;
        try{ b.fn(); }catch(e){}
      }
    }
  }
};
// 注册内置心跳：时钟 / 自动存档 / 音乐（进世界时随 HEART.start 一起运转）
