HEART.beat('autosave', 45000, function(){ if(SETTINGS.autosave){ try{ localStorage.setItem(SAVE_KEY, JSON.stringify({player:player, game:game, saveVer:SAVE_VER})); }catch(e){} } });
HEART.beat('music', 2000, function(){ updateMusic(); });

/* ================================================================
   框架核心 · 指令/动作注册表（仿 MUDCore cmds）
   —— 所有可执行动作统一注册，按钮 / 事件 / 后续指令系统共用入口。
      register(cmd, {label, desc, cond, fn})
      run(cmd) —— 统一分发（先过 cond，再执行）
   ================================================================ */
const CMDS={};
function registerCmd(name, cfg){
  CMDS[name]=cfg||{};
}
function runCmd(name){
  const c=CMDS[name];
  if(!c){ log('（没有这项动作）','sys'); return; }
  if(c.cond && !c.cond()){ if(c.blockMsg) log(c.blockMsg,'sys'); return; }
  c.fn();
}
// —— 注册常用动作（按钮与事件均走此处，便于日后加文字指令） ——
registerCmd('heal', { label:'疗伤', desc:'敷药或运功疗伤', fn:function(){ healAction(); } });
