registerCmd('save', { label:'存档', desc:'保存游戏进度', fn:function(){ saveGame(); } });
registerCmd('look', { label:'环顾', desc:'环顾四周', fn:function(){ look(); } });
registerCmd('move_n', { label:'向北', fn:function(){ moveDir('n'); } });
registerCmd('move_s', { label:'向南', fn:function(){ moveDir('s'); } });
registerCmd('move_e', { label:'向东', fn:function(){ moveDir('e'); } });
registerCmd('move_w', { label:'向西', fn:function(){ moveDir('w'); } });
