function checkAchievements(){
  if(!game.ach) game.ach={};
  ACHIEVEMENTS.forEach(function(a){
    if(game.ach[a.id]) return;
    try{
      if(a.check()){
        game.ach[a.id]=true;
        // 破境成就联动：标记首次破境
        if(a.id==='realmBreak1') game.ach['realmBreak']=true;
        logTitle('—— 成就达成 ·「'+a.name+'」'+(a.tier?'【'+['','铜','银','金'][a.tier]+'】':'')+' ——');
        logInfo('（'+a.desc+'）'+(a.title?'　可佩戴称号「'+a.title+'」！':''));
        a.fn();
        updateSidebar();
      }
    }catch(e){}
  });
}
function achCount(){ return game.ach?Object.keys(game.ach).filter(function(k){ return ACHIEVEMENTS.some(function(a){ return a.id===k; }); }).length:0; }
function achTitles(){ return ACHIEVEMENTS.filter(function(a){ return a.title && game.ach && game.ach[a.id]; }).map(function(a){ return a.title; }); }
function achTierCount(t){ return ACHIEVEMENTS.filter(function(a){ return a.tier===t && game.ach && game.ach[a.id]; }).length; }
// —— 可佩戴称号：侧栏显示 + 名望加成 ——
function equipTitle(title){
  player.title=title||null;
  log('（你如今以「'+title+'」之名行江湖——天下人见你，先敬三分。）','success');
  updateSidebar();
}
function openAchievements(){
  const h=document.createElement('div');
  h.style.cssText='font-size:.8em;color:#ffffff;';
  const head=document.createElement('div'); head.style.cssText='color:#c9c9cf;font-size:.72em;margin-bottom:6px;';
  const done=achCount();
  head.textContent='（江湖簿上，刀痕墨迹——已得 '+done+'/'+ACHIEVEMENTS.length+' 事。铜 '+achTierCount(1)+' · 银 '+achTierCount(2)+' · 金 '+achTierCount(3)+'）';
  h.appendChild(head);
  // 称号佩戴区
  const titles=achTitles();
  const tRow=document.createElement('div'); tRow.style.cssText='margin:6px 0 10px;padding:8px;border:1px solid var(--gold);border-radius:10px;background:rgba(232,184,74,.07);';
  tRow.innerHTML='<div style="color:var(--gold-bright);font-size:.8em;letter-spacing:2px;">可佩戴称号</div>';
  if(!titles.length){
    const e=document.createElement('div'); e.style.cssText='color:#b8b8c0;font-size:.72em;padding:4px 0;'; e.textContent='（完成金质成就即可获得称号——名号出鞘，天下知你。）'; tRow.appendChild(e);
  } else {
    titles.forEach(function(t){
      const b=document.createElement('button'); b.className='btn small '+(player.title===t?'green':''); b.style.cssText='margin:3px;';
      b.textContent=t+(player.title===t?'（佩戴中）':'');
      b.addEventListener('click',function(){ equipTitle(t); document.getElementById('overlay').classList.remove('show'); openAchievements(); });
      tRow.appendChild(b);
    });
    if(player.title && titles.indexOf(player.title)===-1){
      const b=document.createElement('button'); b.className='btn small'; b.style.cssText='margin:3px;'; b.textContent='卸下称号';
      b.addEventListener('click',function(){ equipTitle(null); document.getElementById('overlay').classList.remove('show'); openAchievements(); });
      tRow.appendChild(b);
    }
  }
  h.appendChild(tRow);
  ACHIEVEMENTS.forEach(function(a){
    const got=game.ach&&game.ach[a.id];
    const row=document.createElement('div'); row.className='list-row';
    const tierMark=a.tier?['','◆','◆◆','◆◆◆'][a.tier]:'';
    const tierCls=a.tier===3?'gold':(a.tier===2?'silver':'bronze');
    row.innerHTML='<span class="lname '+(got?tierCls:'')+'">'+(got?'✔ ':'○ ')+a.name+' '+tierMark+'</span><span class="lmeta">'+a.desc+(a.title?'　<span style="color:var(--gold-bright);">称号「'+a.title+'」</span>':'')+'</span>';
    row.style.opacity= got?1:0.55;
    h.appendChild(row);
  });
  openModal('成就 · 江湖簿', ()=>h);
