/* ================================================================
   图鉴 · 收集（仿 MUDCore 的世界记录）
   —— 敌人图鉴 / 人物谱 / 足迹 / 物品收集，四条钩子随游戏推进记录。
   ================================================================ */
// 记录敌人图鉴（战斗开始/击败时）
function codexEnemy(name){
  if(!game.codex) game.codex={};
  if(!game.codex.enemies) game.codex.enemies={};
  game.codex.enemies[name]=true;
}
// 记录人物谱（首次对话/相识）
function codexNpc(name){
  if(!game.codex) game.codex={};
  if(!game.codex.npcs) game.codex.npcs={};
  if(!game.codex.npcs[name]){ game.codex.npcs[name]=true; }
}
// 记录足迹（到访新地点）
function codexPlace(rn){
  if(!game.codex) game.codex={};
  if(!game.codex.places) game.codex.places={};
  game.codex.places[rn]=true;
}
// 记录物品收集（首次获得）
function codexItem(name){
  if(!game.codex) game.codex={};
  if(!game.codex.items) game.codex.items={};
  if(!game.codex.items[name]){ game.codex.items[name]=true; }
}
// 四条钩子接入：战斗 / 对话 / 移动 / 拾取
function hookCodexEnemy(name){ codexEnemy(name); }
function hookCodexNpc(name){ codexNpc(name); }
function hookCodexPlace(rn){ codexPlace(rn); }
function hookCodexItem(name){ codexItem(name); }
// 图鉴面板
function openCodex(){
  const c=game.codex||{};
  const h=document.createElement('div');
  h.style.cssText='font-size:.8em;color:#ffffff;';
  const tabs=document.createElement('div'); tabs.style.cssText='display:flex;gap:6px;margin-bottom:8px;flex-wrap:wrap;';
  const view=document.createElement('div');
  const mkTab=function(label, fn){
    const b=document.createElement('button'); b.className='btn small blue'; b.textContent=label;
    b.addEventListener('click',function(){ document.querySelectorAll('#codex-tabs button').forEach(function(x){ x.classList.remove('blue'); x.classList.add(''); }); b.classList.add('blue'); fn(); });
    b.id='codex-tabs';
    tabs.appendChild(b);
    return b;
  };
  h.appendChild(tabs); h.appendChild(view);
  // —— 敌人图鉴 ——
  mkTab('敌人图鉴', function(){
    view.innerHTML='';
    const en=Object.keys(ENEMIES);
    const seen=c.enemies||{};
    let got=0;
    en.forEach(function(nm){
      const known=!!seen[nm];
      if(known) got++;
      const ed=ENEMIES[nm];
      const row=document.createElement('div'); row.className='list-row';
      row.innerHTML='<span class="lname">'+(known?nm:'？？？')+'</span><span class="lmeta">'+(known?('气血 '+ed.hp+' · 攻 '+ed.atk+' · 防 '+ed.def+(ed.trait?(' · 【'+traitLine(ed.trait)+'】'):'')):'未遭遇')+'</span>';
      row.style.opacity=known?1:0.5;
      view.appendChild(row);
    });
    const head=document.createElement('div'); head.style.cssText='color:#c9c9cf;font-size:.72em;margin-bottom:4px;';
    head.textContent='（见闻录：已遭遇 '+got+'/'+en.length+' 种敌人——交战过的，方能识其底细。）';
    view.insertBefore(head, view.firstChild);
  });
  // —— 人物谱 ——
  mkTab('人物谱', function(){
    view.innerHTML='';
    const seen=c.npcs||{};
    let got=0;
    Object.keys(NPCS).forEach(function(nm){
      if(seen[nm]) got++;
      const npc=NPCS[nm];
      const known=!!seen[nm];
      const row=document.createElement('div'); row.className='list-row';
      row.innerHTML='<span class="lname">'+(known?nm:'？？？')+'</span><span class="lmeta">'+(known?(npc.title||'江湖中人')+' · '+(npc.gender==='女'?'女':'男'):'素未谋面')+'</span>';
      row.style.opacity=known?1:0.5;
      view.appendChild(row);
    });
    const head=document.createElement('div'); head.style.cssText='color:#c9c9cf;font-size:.72em;margin-bottom:4px;';
    head.textContent='（人物谱：已相识 '+got+' 位——江湖之大，相逢即缘。）';
    view.insertBefore(head, view.firstChild);
  });
  // —— 足迹 ——
  mkTab('足迹', function(){
    view.innerHTML='';
    const seen=c.places||{};
