{"file_path": "F:\1\jianlai\JianLai mud\index.html", "new_string": "function equipBonus(){
  const b={crit:0, critDmg:0, dr:0, dodge:0, looks:0, atk:0, def:0, hp:0, mp:0};
  ['weapon','armor','accessory'].forEach(function(slot){
    const it=player.equipment[slot]?itemData(player.equipment[slot]):null;
    if(!it) return;
    if(it.critBonus) b.crit+=it.critBonus;
    if(it.critDmgBonus) b.critDmg+=it.critDmgBonus;
    if(it.drBonus) b.dr+=it.drBonus;
    if(it.dodgeBonus) b.dodge+=it.dodgeBonus;
  });
  const g=player.equipment.garb?itemData(player.equipment.garb):null;
  if(g&&g.looksBonus) b.looks+=g.looksBonus;
  // —— 套装效果：同套装（同名）凑足 2/3 件激活加成 ——
  const setNames=[];
  ['weapon','armor','accessory','garb'].forEach(function(slot){
    const it=player.equipment[slot]?itemData(player.equipment[slot]):null;
    if(it && it.set) setNames.push(it.set);
  });
  if(setNames.length){
    // 统计每套件数（同名套装）
    const count={};
    setNames.forEach(function(s){ count[s]=(count[s]||0)+1; });
    for(const s in count){
      const n=count[s];
      const def=SET_BONUSES[s];
      if(!def) continue;
      if(n>=3 && def.bonus3){ b.atk+=def.bonus3.atk||0; b.def+=def.bonus3.def||0; b.hp+=def.bonus3.hp||0; b.mp+=def.bonus3.mp||0; b.crit+=def.bonus3.crit||0; b.dr+=def.bonus3.dr||0; b.critDmg+=def.bonus3.critDmg||0; }
      else if(n>=2 && def.bonus2){ b.atk+=def.bonus2.atk||0; b.def+=def.bonus2.def||0; b.hp+=def.bonus2.hp||0; b.mp+=def.bonus2.mp||0; b.crit+=def.bonus2.crit||0; b.dr+=def.bonus2.dr||0; b.critDmg+=def.bonus2.critDmg||0; }
    }
  }
  return b;
}
