  '江湖散人':{ bonus2:{atk:4, hp:40}, bonus3:{atk:8, hp:80, crit:0.03}, desc:'浪迹天涯的散人行头——风霜磨砺，自在逍遥。' },
  '书院青衿':{ bonus2:{mp:30, def:2}, bonus3:{mp:60, def:5, critDmg:0.15}, desc:'山崖书院的青衿——腹有诗书，气自华。' },
  '镇妖行者':{ bonus2:{def:5, dr:0.03}, bonus3:{def:10, dr:0.06, atk:6}, desc:'专镇妖邪的行者装束——妖气不敢近身。' },
  '铁血边军':{ bonus2:{atk:6, def:4}, bonus3:{atk:12, def:8, hp:60}, desc:'边关将士的制式甲胄——血火淬炼，百战不折。' }
