function effMaxHp(){ let m=player.maxHp+daoBonus().hp+attrV('gengu')*12+originBonus().hp+equipBonus().hp; ['accessory','weapon','armor'].forEach(function(slot){ const it=player.equipment[slot]?itemData(player.equipment[slot]):null; if(it&&it.hpBonus) m+=it.hpBonus; }); return Math.floor(m*(1+ageBonus().hp/100)); }
function hasMaterials(mat){ for(const k in mat){ if(countItem(k)<mat[k]) return false; } return true; }
function consumeMaterials(mat){ for(const k in mat){ for(let i=0;i<mat[k];i++) removeItem(k); } }

