#map-panel{
  flex:1.1;min-height:0;position:relative;border:1px solid var(--line);
  border-radius:10px;overflow:hidden;background:
    radial-gradient(ellipse at 50% 30%,rgba(120,85,35,.10),transparent 70%),
    linear-gradient(180deg,#0e0e18,#0a0a13);
  box-shadow:inset 0 0 60px rgba(0,0,0,.6);
}
#map-panel::before{
  content:'';position:absolute;inset:0;opacity:.07;pointer-events:none;
  background:var(--bg-image) center/cover no-repeat;
}
#map-head{
  position:absolute;top:0;left:0;right:0;z-index:5;display:flex;justify-content:space-between;
  align-items:center;padding:6px 14px;background:linear-gradient(180deg,rgba(10,10,18,.85),transparent);
  pointer-events:none;
}
#map-head .t{letter-spacing:8px;color:var(--gold);font-size:.85em;}
#map-head .legend{color:var(--ink-dim);font-size:.66em;letter-spacing:1px;}
#map-head .zoom{pointer-events:auto;display:flex;gap:4px;margin-left:8px;}
#map-head .zbtn{background:rgba(20,18,28,.8);border:1px solid rgba(255,255,255,.4);color:var(--gold);font-size:14px;line-height:1;padding:3px 7px;border-radius:6px;cursor:pointer;}
#map-head .zbtn:hover{background:rgba(255,255,255,.2);}
#map-svg{width:100%;height:100%;display:block;cursor:grab;touch-action:none;}
#map-svg.dragging{cursor:grabbing;}
#map-svg .room-node{cursor:pointer;}
#map-svg .room-node .node-ring{fill:rgba(0,0,0,0);stroke:#ffffff;stroke-width:1.5;transition:all .25s;}
#map-svg .room-node:hover .node-ring{stroke:#ffffff;stroke-width:2.5;fill:rgba(255,255,255,.12);}
#map-svg .room-node.current .node-ring{fill:rgba(255,255,255,.28);stroke:#ffffff;stroke-width:2.5;}
#map-svg .room-node.seen .node-ring{stroke:#c0c0c8;}
#map-svg .room-node .node-label{fill:#ffffff;font-size:21px;font-weight:600;text-anchor:middle;font-family:'KaiTi','楷体',serif;pointer-events:none;stroke:rgba(6,6,14,.88);stroke-width:3px;paint-order:stroke;}
#map-svg .room-node.current .node-label{fill:#ffffff;font-weight:bold;}
#map-svg .room-node.seen .node-label{fill:#a8a8b0;}
#map-svg .path-line{stroke:rgba(255,255,255,.32);stroke-width:1.6;stroke-dasharray:4 4;}
#map-svg .path-line.seen{stroke:rgba(255,255,255,.16);}
/* 城镇内部步行：实线（与洲际「虚线=传送」区分） */
#map-svg .path-solid{stroke:rgba(255,255,255,.40);stroke-width:1.8;}
#map-svg .path-solid.seen{stroke:rgba(255,255,255,.20);}
#map-svg .node-fog{fill:rgba(255,255,255,.12);stroke:#9090a0;stroke-width:1;cursor:pointer;}
#map-svg .node-fog text{fill:#b8b8c0;font-size:20px;text-anchor:middle;pointer-events:none;stroke:rgba(6,6,14,.88);stroke-width:3px;paint-order:stroke;}
/* —— 视野可见（望得见未踏足）：淡蓝雾影，地名可辨 —— */
#map-svg .node-vision .vision-ring{fill:rgba(111,179,224,.08);stroke:rgba(111,179,224,.5);stroke-width:1.5;stroke-dasharray:5 4;transition:all .25s;}
#map-svg .node-vision:hover .vision-ring{fill:rgba(111,179,224,.18);stroke:#9cc8e6;stroke-width:2.5;}
#map-svg .node-vision .vision-label{fill:#8fb8d8;font-size:17px;font-weight:600;text-anchor:middle;font-family:'KaiTi','楷体',serif;pointer-events:none;stroke:rgba(6,6,14,.88);stroke-width:3px;paint-order:stroke;}
#map-tip{
  position:absolute;bottom:8px;left:10px;z-index:6;font-size:.7em;color:var(--ink-dim);
  background:rgba(10,10,18,.72);padding:4px 12px;border-radius:18px;letter-spacing:1px;pointer-events:none;
  display:none;align-items:center;gap:6px;max-width:86%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
#map-tip:not(:empty){display:flex;}
#map-tip .tip-btn{
  pointer-events:auto;cursor:pointer;background:rgba(30,26,22,.9);border:1px solid var(--line-soft);
  color:var(--ink-color);font-family:inherit;font-size:.82em;padding:4px 14px;border-radius:14px;letter-spacing:2px;transition:all .2s;
}
#map-tip .tip-btn:hover{border-color:#fff;color:#fff;}
#map-tip .tip-btn.primary{border-color:#fff;color:#fff;background:rgba(50,46,40,.95);}
#map-tip .tip-go{
  pointer-events:auto;cursor:pointer;background:rgba(126,201,138,.16);border:1px solid #7ec98a;
  color:#a5d9ad;font-family:inherit;font-size:.82em;padding:4px 16px;border-radius:14px;letter-spacing:2px;transition:all .2s;
}
#map-tip .tip-go:hover{background:rgba(126,201,138,.3);}
#map-tip .tip-go:disabled{opacity:.45;cursor:not-allowed;background:rgba(120,120,120,.12);border-color:#6a6a72;color:#9a9aa4;}
#map-tip .tip-go:disabled:hover{background:rgba(120,120,120,.12);}
/* —— 三级地图：建筑节点 / 返回节点 —— */
#map-svg .room-node.bld .node-ring{stroke:#9cc8e6;stroke-width:2;stroke-dasharray:4 3;}
#map-svg .node-gate .node-ring{fill:rgba(126,201,138,.10);stroke:#7ec98a;stroke-width:2;stroke-dasharray:5 4;}
#map-svg .node-gate:hover .node-ring{fill:rgba(126,201,138,.22);}
#map-svg .node-gate .node-label{fill:#a5d9ad;font-size:19px;}

