function injectMapDefs(svg){
  if(svg.querySelector('defs')) return;
  const defs=document.createElementNS(SVG_NS,'defs');
  // 连线渐变（从暖金到清淡）——美观且区分主次
  const lg=document.createElementNS(SVG_NS,'linearGradient');
  lg.setAttribute('id','line-grad'); lg.setAttribute('x1','0'); lg.setAttribute('y1','0'); lg.setAttribute('x2','1'); lg.setAttribute('y2','0');
  const s1=document.createElementNS(SVG_NS,'stop'); s1.setAttribute('offset','0'); s1.setAttribute('stop-color','rgba(232,184,74,.55)');
  const s2=document.createElementNS(SVG_NS,'stop'); s2.setAttribute('offset','1'); s2.setAttribute('stop-color','rgba(232,184,74,.12)');
  lg.appendChild(s1); lg.appendChild(s2); defs.appendChild(lg);
  // 节点辉光
  const rg=document.createElementNS(SVG_NS,'radialGradient');
  rg.setAttribute('id','node-glow'); rg.setAttribute('cx','.5'); rg.setAttribute('cy','.5'); rg.setAttribute('r','.5');
  const g1=document.createElementNS(SVG_NS,'stop'); g1.setAttribute('offset','0'); g1.setAttribute('stop-color','rgba(255,255,255,.22)');
  const g2=document.createElementNS(SVG_NS,'stop'); g2.setAttribute('offset','1'); g2.setAttribute('stop-color','rgba(255,255,255,0)');
  rg.appendChild(g1); rg.appendChild(g2); defs.appendChild(rg);
  // 背景网格（水墨舆图感）
  const pat=document.createElementNS(SVG_NS,'pattern');
  pat.setAttribute('id','grid-pat'); pat.setAttribute('width','80'); pat.setAttribute('height','80'); pat.setAttribute('patternUnits','userSpaceOnUse');
  const pl=document.createElementNS(SVG_NS,'path');
  pl.setAttribute('d','M80 0 L0 0 0 80');
  pl.setAttribute('fill','none'); pl.setAttribute('stroke','rgba(255,255,255,.06)'); pl.setAttribute('stroke-width','1');
  pat.appendChild(pl); defs.appendChild(pat);
  svg.insertBefore(defs, svg.firstChild);
}
// —— 地图可见性：已到访(seen) / 视野内可见(vision) / 迷雾(hidden) ——
function mapVisibility(){
  const out={seen:{}, vision:{}};
  const seenSet={};
  (player.visited||[]).forEach(function(rn){ seenSet[rn]=1; });
  for(const rn in ROOMS){ if(seenSet[rn]) out.seen[rn]=1; }
  // 视野：从已到访房间向外 BFS visionRange 步（只标未到访）
  const vr=visionRange();
  const q=[];
  for(const rn in out.seen) q.push(rn);
  const dist={}; q.forEach(function(rn){ dist[rn]=0; });
  while(q.length){
    const cur=q.shift();
    const r=ROOMS[cur];
    if(!r||!r.exits) continue;
    for(const d in r.exits){
      const t=r.exits[d];
      if(!ROOMS[t]) continue;
      if(seenSet[t]) continue;
      const nd=(dist[cur]||0)+1;
      if(nd>vr) continue;
      if(dist[t]===undefined){ dist[t]=nd; q.push(t); out.vision[t]=1; }
    }
  }
  return out;
}
// —— 洲舆图：显示各洲的城镇节点（方框平连，横平竖直；只画可见连线） ——
function renderZhouMap(svg){
  injectMapDefs(svg);
  const L=computeGridLayout();
  const pos=L.pos;
  const HW=120, HH=48;
  const vis=mapVisibility(); // 洲舆图：城镇是否已踏上（seen=到访过该城）
  // 背景网格垫底
  const grid=document.createElementNS(SVG_NS,'rect');
  grid.setAttribute('x',0); grid.setAttribute('y',0); grid.setAttribute('width',L.w); grid.setAttribute('height',L.h);
  grid.setAttribute('fill','url(#grid-pat)');
  svg.appendChild(grid);
  // 洲际连线（正交）：只画「已到访城镇之间」的可见路线，未到访侧用暗虚
  const drawn={};
  CHENG_LINKS.forEach(function(pair){
    const a=pair[0], b=pair[1];
    const pa=pos[a], pb=pos[b];
    if(!pa||!pb) return;
    const key=[a,b].sort().join('|');
    if(drawn[key]) return; drawn[key]=true;
    const aSeen=!!vis.seen[a], bSeen=!!vis.seen[b];
    // 双方皆踏足 → 实线可走；仅一方 → 暗虚线（路的另一头尚在迷雾）
    drawOrthoLink(svg, pa.x, pa.y, pb.x, pb.y, HW, HH, (aSeen&&bSeen)?'path-line':'path-line dim');
  });
  // 按洲分组着色（洲际色板）
  const zhouColors={'宝瓶洲':0,'桐叶洲':1,'北俱芦洲':2,'中土神洲':3,'东胜神洲':4,'南赡部洲':5,'蛮荒':6};
  const palette=['#f0c060','#7ec98a','#9cc8e6','#c49be0','#e8963f','#e88282','#e05555'];
  for(const cid in CHENG_CFG){
    const c=CHENG_CFG[cid];
    const p=pos[cid];
    if(!p) continue;
    const current=player.room===cid;
    const seen=!!vis.seen[cid];
    const g=document.createElementNS(SVG_NS,'g');
    g.setAttribute('class','room-node'+(current?' current':'')+(seen?' seen':''));
    // 外辉光
    const glow=document.createElementNS(SVG_NS,'rect');
    glow.setAttribute('x',p.x-HW-6); glow.setAttribute('y',p.y-HH-6);
    glow.setAttribute('width',HW*2+12); glow.setAttribute('height',HH*2+12); glow.setAttribute('rx',20);
    glow.setAttribute('fill','url(#node-glow)');
    g.appendChild(glow);
    const box=document.createElementNS(SVG_NS,'rect');
    box.setAttribute('x',p.x-HW); box.setAttribute('y',p.y-HH);
    box.setAttribute('width',HW*2); box.setAttribute('height',HH*2);
    box.setAttribute('rx',16);
    box.setAttribute('class','node-ring');
    const zc=palette[zhouColors[c.zhou]]||'#f0c060';
    box.setAttribute('style','stroke:'+zc+';'+(seen?'fill:rgba('+hexToRgb(zc)+',.10);':'')+(current?'fill:rgba(255,255,255,.20);':''));
    const label=document.createElementNS(SVG_NS,'text');
    label.setAttribute('x',p.x); label.setAttribute('y',p.y+7);
    label.setAttribute('class','node-label');
    label.setAttribute('style','font-size:21px;');
    label.textContent=c.name;
    const zt=document.createElementNS(SVG_NS,'text');
    zt.setAttribute('x',p.x); zt.setAttribute('y',p.y-HH-10);
    zt.setAttribute('style','font-size:15px;fill:'+zc+';text-anchor:middle;');
    zt.textContent='· '+c.zhou+' ·'+(c.guard?' ⛉':(c.battle?' ⚔':''));
    g.appendChild(box); g.appendChild(label); g.appendChild(zt);
    if(c.guard){ const gt=document.createElementNS(SVG_NS,'text'); gt.setAttribute('x',p.x); gt.setAttribute('y',p.y+HH+14); gt.setAttribute('class','node-label'); gt.setAttribute('style','font-size:15px;fill:#e88282;'); gt.textContent='需'+(c.guard.need.fame?'名望':'')+(c.guard.need.level?'级':'')+(c.guard.need.degree?'功名':''); g.appendChild(gt); }
    g.style.cursor='pointer';
    g.addEventListener('click',function(){ enterCheng(cid); });
    svg.appendChild(g);
  }
}"}

