  injectMapDefs(svg);
  const cid=game.cheng;
  const L=computeGridLayout();
  const posMap=L.pos;
  const HW=isNei?100:112, HH=isNei?40:44;
  // 本层房间
  const layerRooms=[];
  for(const rn in ROOMS){
    if(isNei){ if(ROOMS[rn].bld===game.bld) layerRooms.push(rn); }
    else { if(ROOMS[rn].area===cid && typeof ROOMS[rn].bld!=='string') layerRooms.push(rn); }
  }
  // 可见性：已到访 / 视野可见 / 迷雾
  const vis=mapVisibility(); // {seen:{rn}, vision:{rn}}
  function isAdjacent(n){ const r=getRoom(player.room); return r && r.exits && Object.values(r.exits).indexOf(n)>-1; }
  function isSeen(n){ return !!vis.seen[n]; }
  function isVision(n){ return !!vis.vision[n]; }
  // 背景网格垫底
  const grid=document.createElementNS(SVG_NS,'rect');
  grid.setAttribute('x',0); grid.setAttribute('y',0); grid.setAttribute('width',L.w); grid.setAttribute('height',L.h);
  grid.setAttribute('fill','url(#grid-pat)');
  svg.appendChild(grid);
  // 连线（正交）：只有「两边都已到访」才画实线（可走）；seen↔vision 画淡虚线（路隐约可见）；
  // 迷雾房间不画线（避免"看得见连得上、实际走不过去"）
  const drawn={};
  layerRooms.forEach(function(rn){
    const r=ROOMS[rn], p1=posMap[rn];
    if(!p1) return;
    for(const dir in r.exits){
      const t=r.exits[dir];
      if(!posMap[t]) continue;
      const key=[rn,t].sort().join('|');
      if(drawn[key]) continue; drawn[key]=true;
      const aSeen=isSeen(rn), bSeen=isSeen(t);
      const aVis=isVision(rn), bVis=isVision(t);
      let cls=null;
      if(aSeen && bSeen) cls='path-solid';          // 可走实线
      else if((aSeen&&bVis)||(bSeen&&aVis)) cls='path-line dim'; // 半边可见的暗虚线
      if(cls) drawOrthoLink(svg, p1.x, p1.y, posMap[t].x, posMap[t].y, HW, HH, cls);
    }
  });
  // 节点（方框）
  layerRooms.forEach(function(rn){
    const r=ROOMS[rn], p=posMap[rn];
    if(!p) return;
    const g=document.createElementNS(SVG_NS,'g');
    const current=player.room===rn;
    const isBld=r.bld===true;
    const seen=isSeen(rn), vision=isVision(rn);
    const hidden=!(seen||vision) && !isBld;
    // 未到访且不可见的建筑：仍显示为迷雾节点（门面可见，内部未探）
    const showFog= hidden || (isBld && !seen);
    if(showFog){
      g.setAttribute('class','node-fog');
      const b2=document.createElementNS(SVG_NS,'rect');
      b2.setAttribute('x',p.x-HW); b2.setAttribute('y',p.y-HH);
      b2.setAttribute('width',HW*2); b2.setAttribute('height',HH*2); b2.setAttribute('rx',12);
      b2.setAttribute('class','node-ring');
      const t2=document.createElementNS(SVG_NS,'text');
      t2.setAttribute('x',p.x); t2.setAttribute('y',p.y+6);
      t2.setAttribute('class','node-label'); t2.setAttribute('style','font-size:18px;fill:#9090a0;');
      t2.textContent='?';
      g.appendChild(b2); g.appendChild(t2);
      g.style.cursor='default';
      g.addEventListener('click',function(){ logInfo('（前方迷雾未散——须先走到跟前，方能探明。）'); });
      svg.appendChild(g);
      return;
    }
    if(vision && !seen){
      // 视野内可见（未踏足）：淡蓝雾影 + 地名可见，可点「前往探索」
      g.setAttribute('class','node-vision');
      const ring=document.createElementNS(SVG_NS,'rect');
      ring.setAttribute('x',p.x-HW); ring.setAttribute('y',p.y-HH);
      ring.setAttribute('width',HW*2); ring.setAttribute('height',HH*2); ring.setAttribute('rx',14);
      ring.setAttribute('class','vision-ring');
      const lbl=document.createElementNS(SVG_NS,'text');
      lbl.setAttribute('x',p.x); lbl.setAttribute('y',p.y+6);
      lbl.setAttribute('class','vision-label'); lbl.setAttribute('style','font-size:'+(isNei?14:15)+'px;');
      let nm=rn;
      if(isNei){ nm=rn.split('·').pop(); }
      else if(nm.indexOf('·')>-1){ nm=nm.split('·').slice(1).join('·'); }
      lbl.textContent='?'+nm;
      g.appendChild(ring); g.appendChild(lbl);
      if(r.bld===true){ const bt=document.createElementNS(SVG_NS,'text'); bt.setAttribute('x',p.x); bt.setAttribute('y',p.y+HH+12); bt.setAttribute('class','node-label'); bt.setAttribute('style','font-size:12px;fill:#9cc8e6;'); bt.textContent='（建筑）'; g.appendChild(bt); }
      g.style.cursor='pointer';
      g.addEventListener('click',function(){
        logInfo('（你望向「'+nm+'」——目力所及，抬脚可探。）');
        discoverRoom(rn); // 前往探索（计入 visited，点亮）
      });
      svg.appendChild(g);
      return;
    }
    // 已到访（seen）：明亮方框 + 名称，可点击行走
    g.setAttribute('class','room-node'+(current?' current':'')+(seen?' seen':'')+(isBld?' bld':''));
    const glow=document.createElementNS(SVG_NS,'rect');
    glow.setAttribute('x',p.x-HW-6); glow.setAttribute('y',p.y-HH-6);
    glow.setAttribute('width',HW*2+12); glow.setAttribute('height',HH*2+12); glow.setAttribute('rx',18);
    glow.setAttribute('fill','url(#node-glow)');
    if(current){ glow.setAttribute('style','fill:rgba(232,184,74,.28);'); }
    g.appendChild(glow);
    const box=document.createElementNS(SVG_NS,'rect');
    box.setAttribute('x',p.x-HW); box.setAttribute('y',p.y-HH);
    box.setAttribute('width',HW*2); box.setAttribute('height',HH*2);
    box.setAttribute('rx',12);
    box.setAttribute('class','node-ring');
    if(isBld) box.setAttribute('style','stroke:#9cc8e6;'+(current?'fill:rgba(156,200,230,.18);':''));
    else if(current) box.setAttribute('style','stroke:#f7d874;fill:rgba(232,184,74,.20);stroke-width:2.5;');
    const label=document.createElementNS(SVG_NS,'text');
    label.setAttribute('x',p.x); label.setAttribute('y',p.y+5);
    label.setAttribute('class','node-label');
    label.setAttribute('style','font-size:'+(isNei?15:16)+'px;');
    let nm=rn;
    if(isNei){ nm=rn.split('·').pop(); }
    else if(nm.indexOf('·')>-1){ nm=nm.split('·').slice(1).join('·'); }
    label.textContent=nm;
    g.appendChild(box); g.appendChild(label);
    const liveN=npcsInRoom(rn).length;
    if(liveN>0){
      const ntag=document.createElementNS(SVG_NS,'text');
      ntag.setAttribute('x',p.x); ntag.setAttribute('y',p.y-HH-8);
      ntag.setAttribute('class','node-label');
      ntag.setAttribute('style','font-size:14px;fill:#c9c9cf;');
      ntag.textContent='人物×'+liveN;
      g.appendChild(ntag);
    }
    if(r.enemies && r.enemies.length){
      const etag=document.createElementNS(SVG_NS,'text');
      etag.setAttribute('x',p.x); etag.setAttribute('y',p.y-HH-26);
      etag.setAttribute('style','font-size:18px;fill:#e05555;text-anchor:middle;font-weight:bold;');
      etag.textContent='·战·';
      g.appendChild(etag);
    }
    const clickable=current||isAdjacent(rn)||isSeen(rn);
    g.style.cursor=(clickable||isBld)?'pointer':'default';
    g.addEventListener('click',function(){
      if(current){ look(); return; }
      if(isBld){ // 建筑：直接入内
        enterBld(rn);
        return;
      }
      if(isAdjacent(rn)){ askMove(rn); }
      else if(isSeen(rn)){ askMove(rn); }
      else if(isVision(rn)){ discoverRoom(rn); }
      else { logInfo('（你还不识此路——须先走到跟前，或开阔视野。）'); }
    });
    svg.appendChild(g);
  });
  // 返回节点（锚定原点，由 applyMapView 平移到视口左上角）
  const back=document.createElementNS(SVG_NS,'g');
  back.setAttribute('class','node-gate');
  const bg=document.createElementNS(SVG_NS,'circle');
  bg.setAttribute('cx',0); bg.setAttribute('cy',0); bg.setAttribute('r',44);
  bg.setAttribute('class','node-ring');
  const bt=document.createElementNS(SVG_NS,'text');
  bt.setAttribute('x',0); bt.setAttribute('y',4); bt.setAttribute('class','node-label');
  bt.textContent=isNei?'↑ 返回':'↑ 返回舆图';
  back.appendChild(bg); back.appendChild(bt);
  back.style.cursor='pointer';
  back.addEventListener('click',function(){ if(isNei) exitToCheng(); else exitToZhou(); });
  svg.appendChild(back);
}"}

