```js
// —— 交互建筑：不直接进——先选择怎么进门（进入 / 敲门 / 翻墙 / 打量） ——
function askEnterBld(bldName){
  const r=ROOMS[bldName]; if(!r) return;
  const h=document.createElement('div');
  h.style.cssText='font-size:.8em;color:#ffffff;';
  const head=document.createElement('div'); head.style.cssText='color:#c9c9cf;font-size:.74em;line-height:1.7;margin-bottom:8px;';
  head.textContent='（你站在「'+bldName+'」门前——'+(r.desc||'门扉半掩，内有乾坤。')+'）';
  h.appendChild(head);
  const mk=function(label, desc, cls, fn){
    const row=document.createElement('div'); row.className='list-row';
    row.innerHTML='<span class="lname">'+label+'</span><span class="lmeta">'+desc+'</span>';
    const b=document.createElement('button'); b.className='btn small '+(cls||''); b.textContent='去做';
    b.addEventListener('click',function(){ document.getElementById('overlay').classList.remove('show'); fn(); });
    row.appendChild(b); h.appendChild(row);
  };
  mk('进入', '推门而入——屋内别有洞天', 'primary', function(){ enterBld(bldName); });
  mk('敲门', '叩门三声，看是否有人应门', '', function(){ knockBld(bldName); });
  mk('翻墙', '趁四下无人，翻墙而入（身法越好越稳）', 'blue', function(){ climbBld(bldName); });
  mk('打量', '先在门外看个究竟', '', function(){ sizeUpBld(bldName); });
  mk('离开', '转身离去，日后再来', '', function(){ renderMap(); });
  openModal(bldName+' · 门前', function(){ return h; });
}
```

再定义 knockBld / climbBld / sizeUpBld：

```js
function knockBld(bldName){
  const r=ROOMS[bldName]; if(!r) return;
  const inner=Object.keys(ROOMS).filter(function(rn){ return ROOMS[rn].bld===bldName; });
  const npcIn = inner.find(function(rn){ return npcsInRoom(rn).length>0; });
  const roll=Math.random();
  if(npcIn){
    const npcName=npcsInRoom(npcIn)[0];
    if(roll<0.5){ // 有人应门
      logNpc(npcName,'“谁啊……来了来了。稍等片刻。”');
      logInfo('（门内传来应答声——片刻后，门开了一条缝。）');
      enterBld(bldName);
    } else {
      logNpc(npcName,'“（门内静了片刻，那人似乎不愿理会。）”');
      logInfo('（你叩门再三，无人应答——只得作罢。）');
    }
  } else {
    if(roll<0.4){ logInfo('（门内无人应答——你推门而入，四下空寂。'); enterBld(bldName); }
    else { logInfo('（你叩门半晌，无人应答——看来主人不在，或是不愿见客。）'); }
  }
}
function climbBld(bldName){
  const r=ROOMS[bldName]; if(!r) return;
  const inner=Object.keys(ROOMS).filter(function(rn){ return ROOMS[rn].bld===bldName; });
  const mj=attrV('minjie');
  const chance=Math.min(0.9, 0.35+mj*0.02+(footPower()-1)*0.1);
  if(Math.random()<chance){
    logInfo('（你借力一跃，翻过墙头，轻巧落地——神不知鬼不觉。）');
    logSkill('（敏捷+轻功，翻墙如履平地。）');
    player.room=inner[0];
    if(player.visited.indexOf(player.room)===-1) player.visited.push(player.room);
    game.mapLevel='nei'; game.bld=bldName; game.cheng=r.area;
    look(); renderMap();
  } else {
    log('（你刚攀上墙头，脚下瓦片一松——“哗啦！”你摔了个七荤八素，还惊动了屋里的人。）','warn');
    player.hp=Math.max(1, player.hp-8);
    if(Math.random()<0.5){ logInfo('（屋里传来脚步声——你只得灰溜溜地翻墙而退。）'); }
  }
}
function sizeUpBld(bldName){
  const r=ROOMS[bldName]; if(!r) return;
  logInfo('（你细细打量「'+bldName+'」——'+(r.desc||'门面普通。')+'）');
  const inner=Object.keys(ROOMS).filter(function(rn){ return ROOMS[rn].bld===bldName; });
  const n=inner.reduce(function(s,rn){ return s+npcsInRoom(rn).length; },0);
  if(n>0) logInfo('（隐约听见里面有人声——约莫 '+n+' 人。'+( (player.aff&&Object.keys(player.aff).some(function(k){ return NPCS[k]&&NPCS[k].home===bldName; })) ?'其中似有故人。':'')+'）');
  else logInfo('（门内静悄悄的——像是无人。）');
  logInfo('（门扉半掩——若要进去，伸手即可推开。）');
}
```

这些函数里用到 `npcsInRoom`、`attrV`、`footPower`、`logNpc`、`logSkill`、`openModal`、`renderMap`、`look`——都是既有函数。`player.aff` 存在。

注意 climbBld 里我直接设 mapLevel='nei' 与 enterBld 一致。

