  const dx=x2-x1, dy=y2-y1;
  if(dx===0 && dy===0) return;
  const sx=x1+(dx>=0?hw:-hw), sy=y1;
  const ex=x2+(dx>=0?-hw:hw), ey=y2;
  const path=document.createElementNS(SVG_NS,'path');
  let d;
  const ax=Math.abs(ex-sx), ay=Math.abs(ey-sy);
  if(ay<3){
    // 同行：水平直线
    d='M'+sx+' '+sy+' L'+ex+' '+ey;
  } else if(ax<3){
    // 同列：垂直直线
    d='M'+sx+' '+sy+' L'+ex+' '+ey;
  } else if(Math.abs(ax-ay)<Math.max(4, Math.min(ax,ay)*0.18)){
    // 正方形对角线（45°）：斜线直连
    d='M'+sx+' '+sy+' L'+ex+' '+ey;
  } else {
    // 其余（最常见）：Z形正交（横-竖-横），直线为主，只在转角处竖一下
    const mx=(sx+ex)/2;
    d='M'+sx+' '+sy+' L'+mx+' '+sy+' L'+mx+' '+ey+' L'+ex+' '+ey;
  }
  path.setAttribute('d',d);
  path.setAttribute('class',cls);
  path.setAttribute('fill','none');
  svg.appendChild(path);
}"}

