}","new_string":"// —— 开局匹配包：按出身 / 境界统一生成 关系网 + 装备 + 道具 + 盘缠 ——
function genStartupPackage(lv, bg){
  const tier= lv>=15?3 : lv>=9?2 : lv>=6?1 : 0;
  // ========== 1) 人物关系网：普通开局也有一群"认得你的人" ==========
  const pool=Object.keys(NPCS).filter(function(n){
    const npc=NPCS[n];
    return npc && !npc.boss && npc.canKill!==false && npc.special!==true && !game.npcDead[n] && n!==player.name;
  });
  if(pool.length){
    // 关系数量：最低 3 个（街坊/故交），境界越高认识的人越多
    const relCount=Math.min(pool.length, 3+tier);
    const used={};
    let made=0;
    for(let i=0;i<relCount;i++){
      let n=jp(pool), t2=0;
      while(used[n] && t2<10){ n=jp(pool); t2++; }
      used[n]=true;
      const npc=NPCS[n];
      // 优先找与出生地沾边的NPC（同乡/同坊），找不到再随缘
      const kind=Math.random();
      let aff=0, note='';
      const local=(bg&&bg.aff&&bg.aff[n])?true:false;
      if(local){ aff=Math.max(25, bg.aff[n]); note='从小便认得你——街坊故里，知根知底'; }
      else if(kind<0.4){ aff=10+tier*6+Math.floor(RNG()*10); note='与你有些旧交，见面便熟络'; }
      else if(kind<0.75){ aff=18+tier*8+Math.floor(RNG()*12); note='久闻你的名头，一见便以礼相待'; }
      else { aff=25+tier*10+Math.floor(RNG()*14); note='曾受你照拂，对你心折，颇有结交之意'; }
      player.aff[n]=Math.max(player.aff[n]||0, Math.min(90,aff));
      logInfo('（你初入江湖，'+(npc.title||'一位人物')+' '+n+' 却已认得你——'+note+'。好感 +'+aff+'）');
      made++;
    }
    if(tier>=2){
      const fameAdd=(tier-2)*12+5;
      gainFame(fameAdd);
      logInfo('（高境入世，名望自随——江湖传你之名，侠名 +'+fameAdd+'。）');
    }
  }
  // ========== 2) 匹配装备：按境界档给一套兜底的兵刃/衣甲 ==========
  const eqMap=[
    {min:0,  weapon:'槐木剑',  armor:'麻布衣',   accessory:null, garb:null},
    {min:3,  weapon:'青锋剑',  armor:'粗布武衣', accessory:null, garb:'青衫长袖'},
    {min:6,  weapon:'游鱼剑',  armor:'法袍',     accessory:'玉佩', garb:'青衫长袖'},
    {min:9,  weapon:'青虹剑',  armor:'三山符袍', accessory:'护心镜', garb:'青衿长衫'},
    {min:12, weapon:'雷纹刀',  armor:'黑铁重甲', accessory:'聚灵珠', garb:'道袍'},
    {min:15, weapon:'山河剑',  armor:'金蚕软甲', accessory:'星辰坠', garb:'道袍'}
  ];
  let eq=eqMap[0];
  for(let i=eqMap.length-1;i>=0;i--){ if(lv>=eqMap[i].min){ eq=eqMap[i]; break; } }
  if(eq.weapon && !player.equipment.weapon) player.equipment.weapon=eq.weapon;
  if(eq.armor && !player.equipment.armor)  player.equipment.armor=eq.armor;
  if(eq.accessory && !player.equipment.accessory) player.equipment.accessory=eq.accessory;
  if(eq.garb && !player.equipment.garb) player.equipment.garb=eq.garb;
  // ========== 3) 匹配道具：干粮 / 伤药 / 丹药 / 材料（出身贫富微调） ==========
  const poor=(bg && bg.gold!=null && bg.gold<=0)?true:false;
  addItem('干粮'); addItem('干粮');
  if(!poor){ addItem('疗伤丹'); addItem('草药'); }
  if(tier>=1) addItem('聚气丹');
  if(tier>=2) addItem('大还丹');
  if(tier>=3) addItem('培元丹');
  if(player.path==='剑修'||player.path==='练气士') addItem('符纸');
  if(player.path==='体修') addItem('兽皮');
  // ========== 4) 盘缠：境界越高，闯江湖的底子越厚 ==========
  if(tier>=1) player.gold+= 50;
  if(tier>=2) player.gold+=150;
  if(tier>=3) player.gold+=400;
  logInfo('（开局行囊已备：兵刃衣甲、干粮伤药、些许盘缠——江湖路远，好歹有个底。）');
  return 1;
}"}

